-- Seed backfill (4 decks): fills any topic still below 30 with the repo's original seed cards.
BEGIN;

-- Seed backfill: Economics|AQA|alevel
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the central economic problem?', 'Scarcity: human wants are unlimited but the resources (factors of production) available to satisfy them are finite, so choices must be made about what to produce, how, and for whom.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'List the four factors of production with their respective rewards.', 'Land (rent), labour (wages), capital (interest), enterprise (profit). Enterprise organises the other three and bears risk.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Define opportunity cost.', 'The value of the next-best alternative forgone when a choice is made. It applies to consumers, firms and governments.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What does a Production Possibility Frontier (PPF) show?', 'The maximum combinations of two goods an economy can produce when all resources are fully and efficiently employed, given the current state of technology. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 25 Q70 32 130 75 T200 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Good X</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">Good Y</text><text x="135" y="105" font-size="9" fill="#0B1E3F">PPF</text></svg>', 4),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What does a point inside the PPF indicate?', 'Productive inefficiency or unemployed/underused resources — output could be increased without sacrificing any other good.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Why is a PPF typically concave to the origin?', 'Because resources are not equally productive in all uses; reallocating them yields increasing opportunity costs as factors better suited to the other good must eventually be transferred.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Distinguish economic growth from economic development.', 'Growth = rise in real GDP (quantitative). Development = broader improvement in living standards including health, education, equality and political freedom (qualitative).', 7),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Distinguish positive and normative statements.', 'Positive statements describe what is and can be tested against evidence. Normative statements involve value judgements about what ought to be and cannot be empirically verified.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the difference between a free market, command and mixed economy?', 'Free market: resources allocated by price signals and private ownership. Command: state plans and owns resources. Mixed: combines private market with public-sector provision and regulation — most real economies.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'State Adam Smith''s ''invisible hand'' idea.', 'Self-interested individuals trading in competitive markets are guided as if by an invisible hand to allocate resources efficiently and benefit society.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Define specialisation and the division of labour.', 'Specialisation: workers/firms/countries focus on the tasks they are best at. Division of labour: breaking production into specialised tasks performed by different workers, raising productivity (Smith''s pin factory).', 11),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Give two advantages and one disadvantage of the division of labour.', 'Advantages: higher productivity from practice; lower training costs per task; faster output. Disadvantage: monotony lowers worker morale, raising turnover and absenteeism.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What three functions does money perform?', 'Medium of exchange (replaces barter), store of value (purchasing power preserved over time), unit of account (common measure of value). Some texts add ''standard of deferred payment''.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Why does an outward shift of the PPF represent economic growth?', 'It signals that potential output has risen — through more or better factors of production (investment, education, immigration) or improved technology — so previously unattainable combinations are now feasible.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the ceteris paribus assumption?', 'Latin for ''other things equal'' — economists isolate the effect of one variable by holding all others constant, an essential simplifying assumption when building models.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Why are economic models simplifications?', 'Because the real economy contains millions of agents and variables; models abstract from detail to identify causal relationships and make predictions, accepting some loss of realism.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Define utility and state the consumer objective assumed by economic theory.', 'Utility is the satisfaction or benefit derived from consuming a good or service. The traditional model assumes the consumer''s objective is utility maximisation: getting the greatest possible satisfaction from a limited budget.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Distinguish total utility from marginal utility and state how they are related.', 'Total utility (TU) is the overall satisfaction from consuming a given quantity; marginal utility (MU) is the addition to TU from one more unit, so MU = change in TU / change in Q. TU rises at a decreasing rate while MU is positive but falling, peaks where MU = 0, and falls once MU is negative. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="25" y1="140" x2="25" y2="15" stroke="#0B1E3F"/><line x1="25" y1="100" x2="210" y2="100" stroke="#0B1E3F"/><path d="M25 100 Q82 25 140 25 Q172 25 200 45" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="25" y1="60" x2="200" y2="121" stroke="#0B1E3F" stroke-width="1.5" stroke-dasharray="3,2"/><line x1="140" y1="25" x2="140" y2="121" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><text x="203" y="46" font-size="9" fill="#0B1E3F">TU</text><text x="203" y="126" font-size="9" fill="#0B1E3F">MU</text><text x="140" y="114" font-size="8" fill="#0B1E3F" text-anchor="middle">Q*</text><text x="208" y="112" font-size="8" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 2),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'State the law of diminishing marginal utility and its two conditions.', 'As successive units of a good are consumed, the additional satisfaction from each extra unit eventually falls. Conditions: it applies within a given time period, and ceteris paribus (tastes, income and consumption of other goods held constant).', 3),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'At what quantity is total utility maximised, and what happens beyond it?', 'Total utility is maximised at the satiation point, where marginal utility equals zero. Beyond it marginal utility is negative, so each further unit reduces total utility. A common error is to say diminishing MU makes TU fall — it only makes TU rise more slowly.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'How does diminishing marginal utility explain the downward-sloping demand curve?', 'A rational consumer buys an extra unit only while its marginal utility is at least equal to the price paid, so MU of the last unit = P. Since MU falls as quantity rises, a lower price is needed to make later units worth buying — the MU curve in money terms is the individual demand curve. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="25" y1="130" x2="25" y2="15" stroke="#0B1E3F"/><line x1="25" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="40" y1="25" x2="185" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="25" y1="50" x2="78" y2="50" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="78" y1="50" x2="78" y2="130" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="25" y1="95" x2="147" y2="95" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="147" y1="95" x2="147" y2="130" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><text x="22" y="53" font-size="8" fill="#0B1E3F" text-anchor="end">P1</text><text x="22" y="98" font-size="8" fill="#0B1E3F" text-anchor="end">P2</text><text x="78" y="142" font-size="8" fill="#0B1E3F" text-anchor="middle">Q1</text><text x="147" y="142" font-size="8" fill="#0B1E3F" text-anchor="middle">Q2</text><text x="188" y="122" font-size="8" fill="#0B1E3F">MU=D</text></svg>', 5),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'State the equi-marginal principle and define consumer equilibrium.', 'A utility-maximising consumer allocates income so that the marginal utility of the last pound spent is equal on every good: MUa/Pa = MUb/Pb = ... = MUn/Pn. Consumer equilibrium is that point — no reallocation of a pound between goods can raise total utility. Note the price in the denominator.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'List the four assumptions of the traditional model of rational economic decision making.', 'Utility (or profit) maximisation; perfect information about all options, prices and outcomes; transitive and consistent preferences; pure self-interest. Two further conditions are often added: unlimited cognitive capacity and unlimited willpower.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Distinguish imperfect information from asymmetric information.', 'Imperfect information means agents lack the complete or accurate information needed to maximise welfare (gaps or inaccuracy). Asymmetric information is the special case where one party to a transaction knows more than the other and can exploit that advantage.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Name two consequences of asymmetric information in insurance markets.', 'Adverse selection: before the contract, high-risk customers are keenest to buy cover, raising premiums and driving out low-risk buyers. Moral hazard: after the contract, being insured makes risky behaviour more likely. Akerlof''s ''market for lemons'' (1970) makes the same point for used cars.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is bounded rationality?', 'Herbert Simon''s idea that agents intend to be rational but are limited by the information they have, their cognitive capacity and the time available. Rather than optimising they satisfice — accepting the first option that is good enough — often by using heuristics.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is bounded self-control, and why is it damaging to the traditional model?', 'Agents know what is in their long-term interest but lack the willpower to act on it (unused gym memberships, abandoned saving plans). It is damaging because the agent has full information and a clear objective and still fails to maximise utility.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Define anchoring, availability bias and herding.', 'Anchoring: over-weighting the first piece of information seen (a ''was £120, now £60'' sticker). Availability bias: judging probability by how easily examples come to mind (over-rating air crash risk after news coverage). Herding: copying the group, e.g. panic buying of fuel.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Define loss aversion and the endowment effect.', 'Loss aversion (Kahneman and Tversky''s prospect theory, 1979): losses are felt roughly twice as strongly as equivalent gains, judged from a reference point rather than total wealth. The endowment effect follows: owning a good raises its value, so the selling price demanded exceeds the buying price offered.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Define framing and present bias (hyperbolic discounting).', 'Framing: the same choice produces different decisions depending on presentation (''90% fat free'' outsells ''contains 10% fat''), which contradicts consistent preferences. Present bias: heavily over-weighting immediate costs and benefits, reversing earlier plans — e.g. taking a high-APR payday loan.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Define choice architecture and a nudge, and name the main policy tools.', 'Choice architecture is the design of the environment in which decisions are made. A nudge alters behaviour predictably without banning options or significantly changing incentives (Thaler and Sunstein''s ''Nudge'', 2008 — ''libertarian paternalism''). Tools: default choice, framing, salience, restricted choice, mandated choice. The Behavioural Insights Team was set up in the Cabinet Office in 2010.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Give two UK examples of behavioural policy and one evaluation point on nudges.', 'Auto-enrolment (phased in from 2012) moved eligible-employee pension participation from roughly 55% in 2012 to over 88% by 2024; England adopted opt-out organ donation in May 2020 under Max and Keira''s Law. Evaluation: nudges are very cheap and preserve choice, but effects can be modest and fade, so for large externalities they complement rather than replace taxes and regulation.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'State the law of demand.', 'Ceteris paribus, as price falls, quantity demanded rises (and vice versa). Demand curves slope downwards because of the income effect, the substitution effect and diminishing marginal utility.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Distinguish a movement along a demand curve from a shift of it.', 'A movement (extension/contraction) is caused by a change in the good''s own price. A shift is caused by a change in any other determinant (income, related-good prices, tastes, expectations, population).', 2),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is consumer surplus?', 'The difference between the maximum price consumers are willing to pay and the price they actually pay — represented by the area below the demand curve and above the market price up to the equilibrium quantity.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Define price elasticity of demand (PED) and give its formula.', 'PED measures the responsiveness of quantity demanded to a change in price. PED = % change in Qd / % change in P. It is normally negative; sign is conventionally ignored.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Name three determinants of PED.', 'Availability and closeness of substitutes; share of income spent on the good; necessity vs luxury; time period (more elastic in the long run); habit/addiction.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Relate PED to total revenue.', 'If demand is price-elastic (|PED| > 1), a price cut raises total revenue. If inelastic (|PED| < 1), a price cut lowers total revenue. At unitary elasticity, revenue is maximised.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Define cross elasticity of demand (XED).', 'XED = % change in Qd of good A / % change in P of good B. Positive XED indicates substitutes (e.g. Coke and Pepsi); negative XED indicates complements (e.g. cars and petrol).', 7),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Define income elasticity of demand (YED) and interpret its sign.', 'YED = % change in Qd / % change in income. Positive: normal good (luxury if YED>1, necessity if 0<YED<1). Negative: inferior good — demand falls as income rises.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'State the law of supply.', 'Ceteris paribus, as price rises, quantity supplied rises. Supply curves slope upwards because higher prices cover higher marginal costs and incentivise producers to expand output.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Name three determinants that shift the supply curve.', 'Costs of production (wages, raw materials), technology, indirect taxes/subsidies, the number of firms, expectations and producer goals. A change in own price moves along the curve, not shifts it.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Define price elasticity of supply (PES).', 'PES = % change in Qs / % change in P. PES depends on spare capacity, ease of stockholding, factor mobility and the time horizon — supply is more elastic in the long run.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'How is market equilibrium determined?', 'Where the demand and supply curves intersect — quantity demanded equals quantity supplied at the market-clearing price. Surplus pushes price down; shortage pushes it up. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="195" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="78" x2="120" y2="78" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="120" y1="78" x2="120" y2="130" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="198" y="30" font-size="9" fill="#0B1E3F">S</text><text x="28" y="81" font-size="9" fill="#0B1E3F" text-anchor="end">P*</text><text x="120" y="145" font-size="9" fill="#0B1E3F" text-anchor="middle">Q*</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 12),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What does the price mechanism do? (Three functions)', 'Signalling (prices convey information about scarcity), incentive (high prices attract producers and ration consumers) and rationing (price rises so demand equals supply when goods are scarce).', 13),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What does producer surplus represent?', 'The difference between the price producers receive and the minimum they would be willing to accept — the area above the supply curve and below the market price.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'Explain joint demand and competitive demand with examples.', 'Joint (complements): goods bought together — printers and ink. Competitive (substitutes): goods bought as alternatives — butter and margarine. Joint supply: producing one good automatically yields another (beef and leather).', 15),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'How does a sales tax (specific tax) affect equilibrium when demand is inelastic?', 'It shifts supply leftward by the tax. With inelastic demand, the consumer bears most of the burden (incidence) — price rises sharply, quantity falls a little, and tax revenue is large.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Distinguish production from productivity.', 'Production = total quantity of output produced. Productivity = output per unit of input (labour productivity = output per worker per hour). Productivity drives long-run living standards.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'State the law of diminishing marginal returns.', 'In the short run, as more variable input is added to a fixed input, the marginal product of the variable input eventually falls. It causes the short-run MC curve to slope upward.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Distinguish fixed and variable costs.', 'Fixed costs do not vary with output (rent, insurance, salaried staff). Variable costs change with output (raw materials, wages of hourly workers). FC + VC = TC.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Define average cost and marginal cost.', 'AC = TC/Q (cost per unit). MC = ΔTC/ΔQ (cost of producing one more unit). MC cuts AC at its minimum because adding a unit cheaper than average pulls average down.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Why is the short-run AC curve U-shaped?', 'Initially, spreading fixed costs over more units lowers AFC and AC; eventually diminishing returns raise AVC and pull AC back up. The minimum is the productively efficient level of output. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 50 Q90 110 130 80 T200 35" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><path d="M40 90 Q100 120 140 95 T200 50" stroke="#0B1E3F" stroke-width="1.5" fill="none" stroke-dasharray="3 2"/><circle cx="125" cy="92" r="2.5" fill="#0B1E3F"/><text x="198" y="35" font-size="9" fill="#0B1E3F">MC</text><text x="198" y="55" font-size="9" fill="#0B1E3F">AC</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">£</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 5),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Define returns to scale.', 'Long-run response of output to a proportional change in all inputs. Increasing returns: output rises more than proportionally. Constant: same proportion. Decreasing: less than proportional.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'List four internal economies of scale.', 'Technical (specialised capital), purchasing (bulk-buy discounts), managerial (specialist managers), financial (cheaper borrowing), marketing, risk-bearing. They lower long-run AC as the firm grows.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What are diseconomies of scale?', 'The rise in long-run AC as a firm grows past its minimum efficient scale, due to coordination problems, communication breakdown, motivational issues and ''X-inefficiency'' from weak supervision.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Distinguish internal and external economies of scale.', 'Internal: arise within the firm as it grows. External: arise within the industry as a whole (skilled labour pool, specialist suppliers, infrastructure clustering — e.g. Silicon Valley).', 9),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Define total, average and marginal revenue.', 'TR = P × Q. AR = TR/Q = price (same as the demand curve). MR = ΔTR/ΔQ. For a price taker AR = MR; for a price maker MR < AR and slopes more steeply.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'State the profit-maximisation rule.', 'Produce where MC = MR (and MC is rising). At this output, the gap between TR and TC is largest.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Distinguish normal and supernormal (abnormal) profit.', 'Normal profit: minimum return needed to keep resources in their current use; counted as a cost in economics. Supernormal profit: any profit above normal — attracts new entrants in competitive markets.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'State the short-run shut-down rule.', 'A firm continues operating in the short run as long as price ≥ AVC, since it can still cover variable costs and contribute to fixed costs. If P < AVC, shut down to limit losses to fixed costs.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Distinguish productive and allocative efficiency.', 'Productive efficiency: producing at minimum AC (no waste of resources). Allocative efficiency: producing the goods consumers value most, where P = MC, maximising society''s welfare.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is X-inefficiency?', 'A failure to minimise costs because firms lack competitive pressure — managerial slack, generous perks, bloated workforces. Common in monopolies and state monopolies.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Why might a firm have other objectives than profit-maximisation?', 'Imperfect information, principal-agent problems (managers maximise their own utility), satisficing (Simon), revenue or sales maximisation (Baumol), market-share targets, social/ethical aims.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'List the four assumptions of perfect competition.', 'Many small buyers and sellers (price takers); identical (homogeneous) products; perfect information; free entry and exit (no barriers).', 1),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Why does a perfectly competitive firm face a horizontal demand curve?', 'Because it is a price taker — its output is too small to influence the market price. AR = MR = market price; any attempt to charge more loses all customers.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What happens to supernormal profits in perfect competition in the long run?', 'New firms are attracted by the profit, supply rises, market price falls until each remaining firm earns only normal profit. The long-run equilibrium has P = AC = MC = MR.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Why is perfect competition both productively and allocatively efficient in the long run?', 'P = minimum AC (productive efficiency) and P = MC (allocative efficiency). Consumers get goods at the lowest possible cost equal to their valuation.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Define monopolistic competition and give an example.', 'Many firms selling slightly differentiated products with low entry barriers — e.g. hairdressers, restaurants. Each has a downward-sloping demand curve from product differentiation but earns only normal profit long run.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'List four characteristics of an oligopoly.', 'Few large firms dominate, high concentration ratio, interdependent decisions, significant barriers to entry, products differentiated or homogeneous, non-price competition important.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is the n-firm concentration ratio?', 'The combined market share of the largest n firms. CR4 above ~50% suggests an oligopolistic structure. UK supermarkets have a high CR4.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Explain the kinked demand curve.', 'In oligopoly, rivals match price cuts (so demand is inelastic below the kink) but ignore price rises (so demand is elastic above). MR has a vertical gap — explains observed price stability despite cost changes. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="35" x2="115" y2="75" stroke="#0B1E3F" stroke-width="1.5"/><line x1="115" y1="75" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="55" x2="115" y2="95" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><line x1="115" y1="115" x2="170" y2="125" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><line x1="115" y1="95" x2="115" y2="115" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><circle cx="115" cy="75" r="2.5" fill="#0B1E3F"/><text x="115" y="68" font-size="8" fill="#0B1E3F" text-anchor="middle">kink</text><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="170" y="135" font-size="9" fill="#0B1E3F">MR</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 8),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Distinguish collusive and non-collusive oligopoly.', 'Collusive: firms cooperate to fix prices/output (cartel) — illegal in UK/EU. Non-collusive: firms compete independently, often using price wars or non-price competition.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What does the prisoners'' dilemma reveal about cartels?', 'Each firm has an individual incentive to cheat by cutting price below the agreed level, even though all are worse off if they all cheat. Explains why cartels are unstable without strong enforcement.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'List three forms of non-price competition.', 'Advertising and branding, product differentiation/quality, after-sales service, loyalty schemes, packaging, location. Used to gain market share without triggering price wars.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Define a pure monopoly and a working monopoly.', 'Pure: a single firm is the only seller. Working/legal: a firm with ≥ 25% market share — the share-of-supply threshold used in UK merger control (Enterprise Act 2002) — so it has significant market power. Abuse of dominance is policed under the Competition Act 1998.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'How does a profit-maximising monopolist set price and output?', 'Output where MC = MR; price read off the demand (AR) curve at that quantity. Result: higher P, lower Q than under perfect competition, with supernormal profit sustained by entry barriers. <svg viewBox="0 0 240 160" width="240" height="160" style="display:block;margin:6px auto"><line x1="30" y1="135" x2="225" y2="135" stroke="#0B1E3F"/><line x1="30" y1="135" x2="30" y2="20" stroke="#0B1E3F"/><line x1="40" y1="35" x2="195" y2="130" stroke="#0B1E3F" stroke-width="1.5"/><line x1="40" y1="35" x2="120" y2="130" stroke="#0B1E3F" stroke-width="1.5"/><path d="M40 90 Q90 130 130 95 T200 60" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><path d="M40 110 Q100 130 140 105 T210 75" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><line x1="30" y1="60" x2="100" y2="60" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="30" y1="92" x2="100" y2="92" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="100" y1="60" x2="100" y2="135" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><rect x="30" y="60" width="70" height="32" fill="#0B1E3F" fill-opacity="0.12"/><text x="198" y="130" font-size="9" fill="#0B1E3F">D=AR</text><text x="123" y="135" font-size="9" fill="#0B1E3F">MR</text><text x="200" y="62" font-size="9" fill="#0B1E3F">MC</text><text x="210" y="78" font-size="9" fill="#0B1E3F">AC</text><text x="28" y="63" font-size="9" fill="#0B1E3F" text-anchor="end">Pm</text><text x="100" y="148" font-size="9" fill="#0B1E3F" text-anchor="middle">Qm</text><text x="60" y="80" font-size="8" fill="#0B1E3F">profit</text></svg>', 13),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Give two costs and two benefits of monopoly.', 'Costs: higher prices, lower output, allocative inefficiency, X-inefficiency. Benefits: economies of scale (lower AC), supernormal profits fund R&D and dynamic efficiency, may be a natural monopoly.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Define a natural monopoly.', 'An industry where long-run AC keeps falling over the entire range of market demand — one firm can supply the market more cheaply than several. Examples: water, electricity grid, rail networks. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 35 C90 90 140 110 200 120" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="40" y1="40" x2="200" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="200" y="35" font-size="9" fill="#0B1E3F" text-anchor="end">LRAC</text><text x="200" y="138" font-size="9" fill="#0B1E3F" text-anchor="end">D</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">£</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 15),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What three conditions are needed for price discrimination?', 'Market power (firm is a price maker), ability to identify groups with different PEDs, and ability to prevent resale (no arbitrage). Examples: peak/off-peak rail fares, student/adult cinema tickets.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Why is the demand for labour called a derived demand?', 'Because firms do not want labour for its own sake — they want the output it produces. Demand for labour is derived from demand for the final good, so demand for bricklayers depends on demand for new housing.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'State the formula for the marginal revenue product of labour.', 'MRP of labour = marginal physical product of labour (MPP) × marginal revenue (MR). In a perfectly competitive product market MR = price, so MRP = MPP × P.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Why is the MRP curve the firm''s demand curve for labour, and why does it slope downwards?', 'A profit-maximising firm hires up to the point where MRP equals the marginal cost of labour, so at any wage it reads the quantity of labour it wants off MRP. It slopes down because diminishing marginal returns make MPP fall in the short run, and in an imperfectly competitive product market MR falls too.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Give four influences that shift the demand for labour curve.', 'Demand for the final product (derived demand); labour productivity, which changes MPP and so MRP; the price of capital relative to labour, driving substitution towards machines; and non-wage employment costs such as employer National Insurance and pension contributions.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What makes the demand for labour more wage elastic?', 'Labour is easily substituted by capital; labour costs are a high share of total costs; demand for the final product is price elastic, so the firm cannot pass on higher wages; and a longer time period, since in the long run production can be redesigned or relocated.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Explain the income and substitution effects of a wage rise, and the shape they produce.', 'Substitution effect: a higher wage raises the opportunity cost of leisure, so the worker supplies more hours. Income effect: a higher wage lets the worker reach a target income with fewer hours, so if leisure is a normal good they supply fewer. At low wages substitution dominates; at high wages income dominates, giving a backward-bending individual supply curve. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="15" stroke="#0B1E3F"/><path d="M55 122 C 95 98 122 72 136 46 C 145 28 132 18 105 17" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Hours of labour</text><text x="28" y="13" font-size="9" fill="#0B1E3F" text-anchor="end">Wage</text><text x="148" y="52" font-size="8" fill="#0B1E3F">income effect</text><text x="60" y="100" font-size="8" fill="#0B1E3F">subs. effect</text></svg>', 6),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What are the net advantages of a job, and what is a compensating wage differential?', 'Net advantages are the whole package of monetary rewards (pay, bonus, pension, holiday) plus non-monetary ones (satisfaction, conditions, security, flexibility, status). A compensating differential is the extra pay needed to attract workers into jobs with poor non-monetary characteristics, such as offshore or night-shift work.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What determines the elasticity of supply of labour to an occupation?', 'The length and cost of the training required, how transferable the skills are, the time period (supply is far more elastic in the long run), the size and mobility of the pool of potential workers, and whether entry is restricted by licensing or registration.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'How are the wage and employment level set in a competitive labour market?', 'Where the market demand for labour (the sum of firms'' MRP curves) equals the market supply of labour. Each firm is a wage taker, so for the firm W = AC of labour = MC of labour. A rise in demand for labour raises both the wage and employment. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="15" stroke="#0B1E3F"/><line x1="45" y1="120" x2="190" y2="35" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="35" x2="190" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="78" x2="117" y2="78" stroke="#0B1E3F" stroke-dasharray="3,2"/><line x1="117" y1="78" x2="117" y2="130" stroke="#0B1E3F" stroke-dasharray="3,2"/><text x="193" y="33" font-size="8" fill="#0B1E3F">S</text><text x="193" y="122" font-size="8" fill="#0B1E3F">D=MRP</text><text x="24" y="80" font-size="8" fill="#0B1E3F" text-anchor="end">We</text><text x="117" y="141" font-size="8" fill="#0B1E3F" text-anchor="middle">Le</text></svg>', 9),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Define monopsony and state the two-step rule for reading the diagram.', 'A monopsony is a labour market with a single or dominant buyer of labour, which is therefore a wage maker. Step 1: employment is set where MC of labour = MRP. Step 2: the wage is read off the supply (AC of labour) curve at that employment level — never off MC or MRP. Both wage and employment are below the competitive outcome.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Why does the marginal cost of labour lie above the supply curve for a monopsonist?', 'Because the supply curve slopes up, hiring one more worker means offering a higher wage — and paying that higher wage to every worker already employed. The marginal cost is therefore the new worker''s wage plus the rise in the existing wage bill, so MC of labour is steeper than and above AC of labour, exactly as MR lies below AR for a monopoly seller.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is the effect of a trade union in a competitive market compared with a monopsony?', 'In a competitive market a union wage above equilibrium raises pay but causes a contraction of labour demand, so employment falls and there is excess supply of labour. Facing a monopsonist it is a bilateral monopoly: the fixed wage makes the MC of labour constant, so the union can raise the wage AND employment towards the competitive level.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What determines trade union bargaining power, and how unionised is the UK?', 'Union density, elasticity of demand for labour, employer profitability, the cost of disruption, legislation on ballots and secondary action, and the state of the economy. Department for Business and Trade figures for 2025 put UK density at 22.4% of employees — 48.5% in the public sector but only 12.1% in the private sector.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'State the UK minimum wage rates that applied from April 2026.', 'National Living Wage £12.71 an hour for workers aged 21 and over, a 4.1% rise from £12.21. National Minimum Wage £10.85 for 18–20 year olds and £8.00 for 16–17 year olds and apprentices. Rates are recommended by the Low Pay Commission and were confirmed in the Autumn Budget of 26 November 2025.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Compare the effect of a minimum wage in a competitive market and in a monopsony.', 'Competitive market: a floor above equilibrium creates excess supply of labour, so employment falls — by more the more elastic labour demand is. Monopsony: the effective MC of labour becomes horizontal at the legal wage, so the firm expands hiring and BOTH the wage and employment rise. UK rises since 1999 have caused smaller job losses than simple theory predicts, usually explained by monopsony power, moderate pre-announced increases, and firms absorbing costs through profits or productivity.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What causes labour market failure, and what is the UK gender pay gap?', 'Causes: geographical and occupational immobility, skills shortages, imperfect information, monopsony power, discrimination, and the positive externalities of training that make it a merit good. Policies: education and training, housing and transport investment, better job matching, and anti-discrimination law. ONS ASHE for April 2025 put the median full-time gender pay gap at 6.9% (£20.27 for men against £18.87 for women), or 12.8% including part-timers — rising from 0.9% at ages 22–29 to 12.5% at 50–59.', 16),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Distinguish income from wealth.', 'Income is a FLOW of money received over a period of time (wages, rent, interest, dividends, profit, transfer payments). Wealth is a STOCK of assets owned at a single point in time, net of debt (property, private pensions, financial and physical assets).', 1),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Explain the relationship between income and wealth.', 'Wealth generates income (rent, dividends, interest) without work; income not consumed is saved and accumulates into wealth, and higher earners save a larger share of each extra pound. Rising asset prices reward existing owners only, and inheritance passes the stock on intact — so the two reinforce each other across generations.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What does a Lorenz curve show?', 'The cumulative % of the population (poorest first) against the cumulative % of income they receive. The 45-degree line is perfect equality; the further the curve bows below it, the greater the inequality. It must run from (0,0) to (100,100). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="30" y1="130" x2="150" y2="20" stroke="#0B1E3F" stroke-width="1.5"/><path d="M30 130 Q110 120 150 20" stroke="#0B1E3F" stroke-width="1.5" fill="none" stroke-dasharray="3 2"/><text x="103" y="84" font-size="9" fill="#0B1E3F">A</text><text x="100" y="118" font-size="9" fill="#0B1E3F">B</text><text x="153" y="18" font-size="8" fill="#0B1E3F">45 line</text><text x="152" y="62" font-size="8" fill="#0B1E3F">Lorenz</text><text x="32" y="16" font-size="9" fill="#0B1E3F">% income</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">% population</text></svg>', 3),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'How is the Gini coefficient calculated and interpreted?', 'Gini = A / (A + B), where A is the area between the 45-degree line and the Lorenz curve and B is the area beneath the Lorenz curve. 0 = perfect equality (A = 0); 1 = perfect inequality (B = 0). A rising Gini means inequality is increasing. Often quoted as a percentage from 0 to 100.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Give the UK Gini coefficients for income and for wealth.', 'Income (DWP Households Below Average Income, 2024/25): 33% before housing costs and 37% after housing costs. Wealth (ONS Wealth and Assets Survey, April 2020 to March 2022, Great Britain): 0.59. Wealth is therefore far more unequally distributed than income. OECD comparisons put UK income inequality among the highest in Europe, below the United States.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'List the AQA causes of inequality in the distribution of income and wealth.', 'Wage differentials; unemployment; age and the life cycle; inheritance; ownership of assets; differences in human capital; discrimination; household composition.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'State the strengths and limitations of the Gini coefficient.', 'Strengths: one number, easy to compare across countries and over time; sensitive to the whole distribution; widely published. Limitations: two very different distributions can share a Gini; it does not say whether inequality arises at the top or the bottom; it ignores absolute living standards; surveys under-record top incomes.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Give the UK quintile and decile income shares.', 'In 2023/24 the top fifth of individuals received 35% of total disposable household income and the bottom fifth received 8% (a quintile ratio of about 4.4). In 2024/25 a couple with no children needed under £366 a week before housing costs for the lowest tenth, and at least £1,358 a week for the highest tenth — 3.7 times as much.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the difference between income measured before and after housing costs?', 'BHC includes the money later spent on rent or mortgage interest; AHC deducts rent, mortgage interest, water charges and buildings insurance first. Housing takes a larger share of low incomes, so AHC is always more unequal — 33% BHC against 37% AHC in 2024/25 — and is the better guide to living standards for renters.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Distinguish absolute poverty from relative poverty.', 'Absolute poverty: income too low to afford basic necessities, measured against a fixed real threshold. Relative poverty: income below the UK official line of 60% of contemporary median household income, equivalised for household size. Growth that lifts all incomes proportionately cuts absolute poverty but leaves relative poverty unchanged; a recession that cuts the median can lower measured relative poverty.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Give the UK relative poverty figures for 2024/25.', '20% of individuals were in relative low income after housing costs, unchanged on 2023/24. Relative child poverty AHC was 31%, and has been between 27% and 31% every year since 2001/02. The rate was 45% for children in families with three or more children and 58% for children in workless families. In July 2026 the government projected relative child poverty AHC would fall by 400,000 by 2029/30.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Summarise the Joseph Rowntree Foundation UK Poverty 2026 findings.', 'Using 2023/24 data: 14.2 million people, 21% of the population, were in poverty, including 4.5 million children (about 3 in 10) and 7.9 million working-age adults; around 3 in 20 pensioners. 6.8 million people were in very deep poverty (income at most two-thirds of the poverty line) — the highest number and share on record since 1994/95. About 3.8 million people, including around 1 million children, experienced destitution in 2022.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the composition of UK household wealth?', 'ONS Wealth and Assets Survey, April 2020 to March 2022: net property 40%, private pension 35%, net financial 14%, physical 10%. The wealthiest tenth of households held around 43% of all wealth and needed £1,200,500 or more; the least wealthy half held about 9%. Most UK wealth is therefore illiquid, tied up in housing and pensions.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Explain the poverty trap and the unemployment trap.', 'Poverty trap: a low-income household raising its earnings pays income tax and NICs while losing means-tested benefits, so its effective marginal tax rate is very high and the net gain is small. The Universal Credit taper has been 55% since November 2021. Unemployment trap: out-of-work income is close to net income in work, so the replacement ratio (out-of-work income / in-work income) is high and there is little incentive to take a job. Both are examples of government failure.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Compare means-tested and universal benefits.', 'Means-tested (Universal Credit, Pension Credit): better targeted, lower payment cost, but incomplete take-up through stigma and complexity, high administration cost, and a withdrawal taper that creates the poverty trap. Universal (state pension, free schooling, NHS treatment): full take-up, no stigma, no taper and broad political support, but very expensive and much of the money goes to households that do not need it.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Explain the equity-efficiency trade-off and the Laffer curve argument.', 'Equity is fairness (normative); equality is a factual description of the distribution. Redistribution may improve equity at the cost of efficiency — Okun called it carrying money in a leaky bucket. High marginal rates may weaken incentives to work, train, take risk or stay in the country. The Laffer curve shows revenue rising with the tax rate up to t*, then falling as disincentives, avoidance and evasion dominate; it shows that some rate maximises revenue, not where that rate lies. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 130 Q110 -50 180 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="110" y1="40" x2="110" y2="130" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="30" y1="40" x2="110" y2="40" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><text x="110" y="142" font-size="9" fill="#0B1E3F" text-anchor="middle">t*</text><text x="28" y="43" font-size="8" fill="#0B1E3F" text-anchor="end">Rmax</text><text x="32" y="16" font-size="9" fill="#0B1E3F">Revenue</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Tax rate</text></svg>', 16),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Define market failure.', 'When the free market fails to allocate resources efficiently, leading to a loss of social welfare. Includes externalities, public goods, information failure, monopoly power and inequality.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Distinguish private, external and social cost.', 'Private cost: borne by the producer/consumer. External cost: spillover onto third parties (pollution). Social cost = private + external. The free market ignores external costs, leading to overproduction.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'How do you identify a negative production externality on a diagram?', 'MSC lies above MPC. The free-market output (where MPB = MPC) exceeds the socially optimum output (where MSB = MSC), creating a deadweight welfare loss triangle. <svg viewBox="0 0 240 150" width="240" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="225" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="200" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="200" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="65" y1="125" x2="220" y2="22" stroke="#0B1E3F" stroke-width="1.5" stroke-dasharray="3 2"/><polygon points="115,75 145,55 145,90" fill="#B00020" fill-opacity="0.3"/><text x="203" y="125" font-size="9" fill="#0B1E3F">D=MPB</text><text x="203" y="30" font-size="9" fill="#0B1E3F">MPC</text><text x="223" y="20" font-size="9" fill="#0B1E3F" text-anchor="end">MSC</text><text x="118" y="80" font-size="8" fill="#B00020">DWL</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="225" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 3),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What are merit and demerit goods?', 'Merit goods: undervalued by consumers, underconsumed (education, healthcare). Demerit goods: overvalued, overconsumed (cigarettes, alcohol). Reflect information failure and positive/negative externalities.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'State the two characteristics of a public good.', 'Non-rival (one person''s use does not reduce another''s) and non-excludable (no one can be prevented from using it). Examples: street lighting, national defence. Free-rider problem leads to under-provision.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the free-rider problem?', 'Because public goods are non-excludable, individuals can benefit without paying. Profit-maximising firms cannot recoup costs, so the good is under-provided by the market — justifying state provision.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'How does asymmetric information cause market failure?', 'When one party in a transaction has more information than the other, leading to adverse selection (used-car market — Akerlof''s lemons) and moral hazard (insured drivers take more risks).', 7),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Evaluate an indirect tax to correct a negative externality.', 'Strengths: internalises external cost (Pigouvian), generates revenue to compensate victims, signals harm. Weaknesses: hard to set at exactly MEC, regressive, may push activity into black markets, inelastic demand limits effect on quantity.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'How does a tradeable pollution permit (cap-and-trade) work?', 'Government caps total emissions and issues permits. Firms that pollute below their allowance sell surplus permits; heavy polluters must buy. Market price of permits reflects MEC; cap can be tightened over time. Used by the EU ETS and, since 2021, the separate UK ETS.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is a subsidy and a likely diagrammatic effect?', 'A government grant that reduces production cost or consumption price. It shifts supply rightward (or demand rightward if to consumers), raising output to the socially optimum level for goods with positive externalities.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Compare maximum and minimum prices.', 'Maximum (price ceiling) below equilibrium creates a shortage and possible black market (e.g. rent controls). Minimum (price floor) above equilibrium creates a surplus and may need government to buy the excess (the EU CAP''s intervention buying, historically; the UK National Living Wage is a wage floor). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="195" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="50" x2="205" y2="50" stroke="#B00020" stroke-width="1.2"/><line x1="30" y1="105" x2="205" y2="105" stroke="#B00020" stroke-width="1.2" stroke-dasharray="4 2"/><text x="208" y="52" font-size="9" fill="#B00020">P min (floor)</text><text x="208" y="107" font-size="9" fill="#B00020">P max (ceiling)</text><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="198" y="30" font-size="9" fill="#0B1E3F">S</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 11),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Why might competition policy be needed?', 'To prevent abuse of monopoly power — anti-competitive mergers, predatory pricing, price-fixing cartels — and protect consumers from high prices and low choice. Enforced by the CMA in the UK.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Distinguish privatisation, deregulation and nationalisation.', 'Privatisation: transfer of state assets to private sector. Deregulation: removal of restrictive rules to allow competition. Nationalisation: transfer of private firms into state ownership.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is regulatory capture?', 'When the regulator comes to act in the interests of the industry it regulates rather than consumers, due to lobbying, revolving doors of personnel, or asymmetric information.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Define government failure.', 'When intervention to correct market failure produces a worse allocation of resources — caused by information gaps, unintended consequences, administrative costs, lobbying and short-termism.', 15),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Give an example of unintended consequences of government intervention.', 'Rent controls reducing housing supply and quality; cigarette taxes funding smuggling; subsidies for biofuels raising food prices; minimum alcohol pricing reducing problem drinking but hitting low-income moderate drinkers.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'List the four main macroeconomic objectives.', 'Sustainable economic growth, low and stable inflation (~2% CPI), low unemployment (full employment), satisfactory balance of payments on current account. Often add: budget balance, fairer income distribution, environmental sustainability.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish nominal and real GDP.', 'Nominal GDP = output valued at current prices. Real GDP = output valued at constant (base-year) prices. Real GDP strips out inflation, so changes in real GDP reflect actual changes in output.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Why use GDP per capita instead of total GDP?', 'Total GDP rises with population. Dividing by population reflects average income/output per person — a better proxy for living standards across countries of different size.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Give three limitations of GDP as a measure of welfare.', 'Ignores income distribution; excludes the informal/black economy and household production; ignores environmental damage; says nothing about leisure, health or political freedom.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the Human Development Index?', 'A UN composite index combining life expectancy, mean/expected years of schooling and GNI per capita (PPP) into a 0-1 score. Captures more dimensions of welfare than GDP alone.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is CPI calculated?', 'A weighted average of the prices of a representative basket of goods and services consumed by a typical household, weights based on Living Costs and Food Survey. Updated annually.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish CPI from RPI.', 'CPI excludes most housing costs and uses a geometric mean (substitution effect) — generally lower. RPI includes mortgage interest and council tax and uses arithmetic mean. Bank of England targets CPI.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'List three limitations of CPI.', 'Slow to capture quality changes; excludes owner-occupiers'' housing costs (CPIH includes them); basket is updated annually but tastes can change quickly; it is an average household''s basket, so it does not reflect any particular household''s spending pattern.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is unemployment measured (UK)?', 'Two main methods: claimant count (those receiving JSA/Universal Credit) — narrow and quick; ILO/Labour Force Survey (out of work, actively sought work in the last four weeks and available to start within two weeks) — internationally comparable, broader.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Define the activity (participation) rate.', 'The economically active population (employed + unemployed) as a percentage of the working-age population. Rises if more women, students or older people enter the labour force.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What does the balance of payments record?', 'All economic transactions between residents of the UK and the rest of the world over a period. Made up of the current account, capital account and financial account; sum should equal zero (with errors and omissions).', 11),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'List the four parts of the current account.', 'Trade in goods, trade in services, primary income (wages/investment income from abroad), secondary income (transfers — remittances, EU/UN payments, foreign aid).', 12),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What does an index number tell you?', 'It re-bases a series so that the value in a chosen base year equals 100. Other values express the percentage change relative to that base, simplifying comparison over time.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the difference between GDP and GNI?', 'GDP measures output produced within a country''s borders. GNI measures income earned by that country''s residents wherever produced. GNI = GDP + net primary income from abroad.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Define purchasing power parity (PPP).', 'An exchange rate that equalises the cost of a basket of goods in two countries. Using PPP rather than market rates makes cross-country GDP comparisons more meaningful — The Economist''s Big Mac Index is a popular illustration.', 15),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish absolute from relative poverty.', 'Absolute: income too low to afford basic essentials (World Bank: $3.00 a day at 2021 PPP since June 2025; previously $2.15 at 2017 PPP). Relative: income below a threshold (commonly 60% of median income in the UK) — measures inequality more than survival.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Write the AD equation.', 'AD = C + I + G + (X − M). Consumption + investment + government spending + net exports.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Why does AD slope downwards?', 'Real-balance effect (lower price level raises real wealth and consumption); interest-rate effect (lower P -> lower money demand -> lower r -> more I); international trade effect (lower P makes exports more competitive).', 2),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Name three determinants of consumption.', 'Disposable income, interest rates, wealth (housing/financial), consumer confidence, expectations, availability of credit, taxation. The marginal propensity to consume falls as income rises.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Distinguish gross and net investment.', 'Gross investment = total spending on new capital goods. Net investment = gross investment minus capital depreciation (replacement). Net investment expands the capital stock and productive capacity.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Give three determinants of investment.', 'Expected returns/animal spirits, interest rates, business confidence, taxation/allowances, technology, retained profits, the accelerator effect (changes in demand drive investment).', 5),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'List four causes of an increase in AD.', 'Cuts in income tax, lower interest rates, weaker pound (boosts X, raises M cost), rising house prices, rising consumer/business confidence, higher government spending, faster world growth.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Distinguish SRAS and LRAS.', 'SRAS: upward-sloping; in the short run, higher P with sticky wages raises profit and output. LRAS: vertical at full-employment output (Yfe) on the classical view, or upward-sloping/curved on the Keynesian view (spare capacity).', 7),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'List three factors that shift LRAS.', 'Quantity/quality of labour (immigration, education), capital stock and investment, technology and productivity, enterprise/incentives, government supply-side policy (deregulation, infrastructure).', 8),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Compare classical and Keynesian LRAS curves.', 'Classical: vertical at Yfe — output cannot exceed potential, so AD changes only affect P. Keynesian: horizontal at low output, upward-sloping with spare capacity, vertical near Yfe — AD matters at low output. <svg viewBox="0 0 460 160" width="460" height="160" style="display:block;margin:6px auto"><g><line x1="30" y1="135" x2="200" y2="135" stroke="#0B1E3F"/><line x1="30" y1="135" x2="30" y2="20" stroke="#0B1E3F"/><line x1="140" y1="135" x2="140" y2="25" stroke="#0B1E3F" stroke-width="1.5"/><line x1="40" y1="30" x2="180" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="200" y="148" font-size="9" fill="#0B1E3F" text-anchor="end">Y</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="143" y="20" font-size="9" fill="#0B1E3F">LRAS</text><text x="183" y="125" font-size="9" fill="#0B1E3F">AD</text><text x="115" y="155" font-size="9" fill="#0B1E3F" text-anchor="middle">Classical</text></g><g><line x1="260" y1="135" x2="440" y2="135" stroke="#0B1E3F"/><line x1="260" y1="135" x2="260" y2="20" stroke="#0B1E3F"/><path d="M260 110 L320 110 Q360 100 380 60 L380 25" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="270" y1="35" x2="420" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="440" y="148" font-size="9" fill="#0B1E3F" text-anchor="end">Y</text><text x="258" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="383" y="22" font-size="9" fill="#0B1E3F">LRAS</text><text x="423" y="125" font-size="9" fill="#0B1E3F">AD</text><text x="350" y="155" font-size="9" fill="#0B1E3F" text-anchor="middle">Keynesian</text></g></svg>', 9),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Define the multiplier and give the formula.', 'The ratio of final change in real GDP to the initial change in injections. k = 1/(1 − MPC) = 1/MPS in a closed economy with no government; in an open economy k = 1/(MPS + MPT + MPM).', 10),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What determines the size of the multiplier?', 'The marginal propensities to consume (raises k) and to withdraw — save, tax, import (lowers k). Also depends on spare capacity: with little spare capacity, extra spending mostly raises prices.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'List the injections and withdrawals in the circular flow.', 'Injections: investment (I), government spending (G), exports (X). Withdrawals: saving (S), taxation (T), imports (M). Equilibrium: I + G + X = S + T + M.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the accelerator effect?', 'The relationship by which a change in the rate of growth of output causes a much larger proportional change in investment, since firms only invest when expected demand growth justifies new capacity.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'How does an outward shift of AD affect P and Y on a Keynesian AS curve?', 'On the horizontal section: Y rises with P unchanged. On the upward-sloping section: P and Y both rise. On the vertical section: P rises with Y unchanged (pure inflation).', 14),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'Why is consumer confidence important to AD?', 'Confidence shapes household saving and borrowing decisions, especially for big-ticket items. Falling confidence raises saving (precautionary motive) and lowers C, contracting AD.', 15),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is Say''s Law and which school accepts it?', 'Say''s Law: ''supply creates its own demand'' — production generates incomes that are spent on output. Accepted by classical economists, rejected by Keynes who argued saving may exceed investment.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Distinguish actual and trend (potential) growth.', 'Actual growth = change in real GDP year on year. Trend growth = the long-run sustainable rate at which the economy can grow without rising inflation, set by the supply-side fundamentals.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'List the four phases of the business cycle.', 'Recovery, boom (peak), slowdown, recession (trough). A recession is technically two consecutive quarters of negative real GDP growth.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'List four potential benefits of economic growth.', 'Higher living standards, higher tax revenue, lower unemployment, easier to redistribute, more government spending on public services, fiscal dividend, business confidence.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Give three costs of rapid economic growth.', 'Demand-pull inflation, current-account deficit (rising imports), environmental damage, widening inequality, resource depletion, working-time pressure on welfare.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Distinguish demand-pull and cost-push inflation.', 'Demand-pull: AD rises faster than AS — ''too much money chasing too few goods''. Cost-push: rising costs (wages, oil, taxes, weaker pound) shift SRAS leftward, raising P and lowering Y (stagflation possible).', 5),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Give the Fisher equation of exchange.', 'MV = PT. Money supply × velocity of circulation = price level × volume of transactions. Monetarists assume V and T are stable, so changes in M cause proportional changes in P.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'List four costs of high inflation.', 'Erodes purchasing power; menu costs; shoe-leather costs; uncertainty deters investment; loss of international competitiveness; income redistribution from creditors to debtors; ''fiscal drag''.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Why is deflation a problem?', 'Consumers delay purchases waiting for lower prices, depressing AD. Real value of debt rises, increasing default risk and bank stress (debt-deflation, Fisher 1933). Hard for central banks to escape with rates at zero.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'List four causes of unemployment.', 'Cyclical (demand-deficient), structural (mismatched skills/regions), frictional (between jobs), seasonal, real-wage (wages above clearing), classical/voluntary.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Give four costs of unemployment.', 'Lost output (operating inside PPF), lower tax revenue, higher benefits, hysteresis (long-term unemployed lose skills), social problems (mental health, crime), inequality.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What does the short-run Phillips curve show?', 'A short-run inverse relationship between inflation and unemployment — lower unemployment requires higher inflation. Fitted by Phillips (1958) to UK data from 1861-1957 and relied on through the 1960s; it broke down in the 1970s under stagflation. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 35 Q90 60 130 95 T200 125" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="200" y="35" font-size="9" fill="#0B1E3F" text-anchor="end">SRPC</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">π</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">U</text></svg>', 11),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What does the long-run Phillips curve look like and why?', 'Vertical at the Natural Rate of Unemployment (NAIRU). Friedman: any attempt to push unemployment below NAIRU only raises inflation as workers update expectations. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="120" y1="130" x2="120" y2="25" stroke="#0B1E3F" stroke-width="1.5"/><path d="M40 50 Q70 65 100 90 T160 130" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><path d="M70 35 Q100 50 130 75 T190 125" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><text x="123" y="22" font-size="9" fill="#0B1E3F">LRPC</text><text x="170" y="125" font-size="8" fill="#0B1E3F">SRPC</text><text x="120" y="145" font-size="9" fill="#0B1E3F" text-anchor="middle">NAIRU</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">π</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">U</text></svg>', 12),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'List two causes of a current-account deficit.', 'Strong domestic demand (sucking in imports), overvalued exchange rate, low productivity/competitiveness, deindustrialisation, slow growth in trading partners, high domestic inflation.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'Why might a current-account deficit not be a problem?', 'It can reflect productive investment financed by capital inflows; reserve-currency status (US dollar) means the deficit can be funded easily; consumers benefit from cheap imports.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'How does the Marshall-Lerner condition relate to a depreciation?', 'A depreciation improves the current-account balance only if |PEDx| + |PEDm| > 1. Short-run elasticities are low (J-curve), so the deficit may worsen before improving. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="80" x2="205" y2="80" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 80 Q70 130 110 95 T200 25" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="50" y1="78" x2="50" y2="82" stroke="#0B1E3F"/><text x="50" y="95" font-size="8" fill="#0B1E3F" text-anchor="middle">depreciation</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">CA balance</text><text x="205" y="78" font-size="9" fill="#0B1E3F" text-anchor="end">time</text></svg>', 15),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is hysteresis in the labour market?', 'The persistence of unemployment after the original shock has passed, because the long-term unemployed lose skills, motivation and employability — raising the natural rate.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'List three roles of financial markets.', 'Channel funds from savers to borrowers, allocate capital efficiently, provide liquidity, price assets and risk, allow firms and governments to raise capital.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Distinguish the money market from the capital market.', 'Money market: short-term debt instruments (under one year — Treasury bills, certificates of deposit, commercial paper). Capital market: long-term funds (shares and bonds with maturities of >1 year).', 2),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the inverse relationship between bond prices and yields?', 'A bond pays a fixed coupon. If its market price falls, the coupon represents a higher % of the price — yield rises. Conversely, when bond demand rises, prices rise and yields fall.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'List three functions of commercial banks.', 'Accept deposits, make loans, provide payment services. Also offer foreign exchange, financial advice and credit/debit cards. Profit comes from the spread between deposit and loan interest rates.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'How do banks create credit?', 'When a bank makes a loan, it credits the borrower''s deposit account, expanding the money supply. Constrained by required reserves, capital ratios and demand for loans.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'List the four functions of a central bank.', 'Sole issuer of banknotes in England and Wales, banker to government, banker to commercial banks, lender of last resort. Conducts monetary policy and oversees financial stability (Prudential Regulation Authority in UK).', 6),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Define moral hazard in banking.', 'When the protection offered by deposit insurance, bailouts or ''too big to fail'' status encourages banks to take excessive risk because they bear less of the downside.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Outline the 2007-09 financial crisis in three sentences.', 'US sub-prime mortgages were bundled into mortgage-backed securities and sold globally. Defaults rose, exposing leveraged banks to huge losses; interbank lending froze. Major banks failed (Lehman) or were bailed out, triggering a global recession.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is monetary policy?', 'The use of interest rates and the money supply to influence AD and meet the inflation target. In the UK, set by the Bank of England''s nine-member Monetary Policy Committee, targeting 2% CPI.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Through what four channels does Bank Rate transmit to inflation?', 'Market interest rates (mortgages, savings), asset prices (housing, shares), confidence/expectations, exchange rate. Each affects C, I, X-M and ultimately AD and inflation, with lags of 12-24 months.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is quantitative easing (QE)?', 'A central bank creates new money electronically to buy government bonds (and other assets), pushing up bond prices, lowering long-term yields, raising asset prices and bank reserves to stimulate AD when Bank Rate is near zero.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Give two limitations of monetary policy.', 'Liquidity trap (rates near zero cannot fall further); time lags; uncertain transmission via banks; if banks won''t lend or households deleverage, low rates have little effect; widens inequality (asset-price boom).', 12),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Distinguish micro- and macro-prudential regulation.', 'Microprudential focuses on stability of individual banks (capital, liquidity ratios). Macroprudential targets the financial system as a whole, e.g. counter-cyclical capital buffers, loan-to-income limits — overseen by the FPC in the UK.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the difference between liquidity and solvency?', 'Liquidity: ability to meet short-run cash demands without distressed sale. Solvency: assets exceed liabilities. A bank can be solvent but illiquid (Northern Rock 2007).', 14),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What are the Basel III capital requirements aimed at?', 'Strengthening bank resilience by raising minimum core capital ratios, introducing leverage and liquidity coverage ratios, and adding counter-cyclical buffers.', 15),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'Define the term structure (yield curve) of interest rates.', 'The relationship between yields on bonds of equal credit quality but different maturities. Normally upward-sloping; an inverted curve (long < short) often precedes a recession.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Define fiscal policy.', 'The use of government spending (G) and taxation (T) to influence AD, redistribute income and provide public goods. Set by the Treasury in the annual Budget.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Distinguish direct and indirect taxes.', 'Direct: levied on income/wealth (income tax, NI, corporation tax) — paid by the person on whom it''s charged. Indirect: levied on spending (VAT, excise duties, fuel duty) — incidence can shift between buyer and seller.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Define progressive, proportional and regressive taxes.', 'Progressive: average tax rate rises with income (UK income tax). Proportional: flat % of income. Regressive: average rate falls as income rises (VAT, council tax).', 3),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'List the four canons of taxation (Adam Smith).', 'Equity (ability to pay), certainty (clear amount/timing), convenience (easy to pay), economy (low collection cost). Modern additions: efficiency, flexibility, transparency.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the difference between a budget deficit and the national debt?', 'A budget deficit is the gap between G and T in a single year (a flow). The national debt is the cumulative total of past borrowing (a stock). The deficit adds to the debt.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Distinguish cyclical and structural budget deficits.', 'Cyclical: arises automatically when output is below trend (lower tax, higher benefits). Structural: persists at full employment, signalling that fiscal policy is fundamentally unsustainable.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Define automatic stabilisers.', 'Features of the tax/benefits system that dampen the cycle without explicit policy change: tax revenues fall and benefits rise in a recession; both reverse in a boom.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Describe expansionary fiscal policy and a likely effect on AD.', 'Cuts in taxes or rises in G shift AD right via the multiplier, raising output and employment in the short run, especially in a recession with spare capacity.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is crowding out?', 'When higher government borrowing pushes up interest rates and absorbs available savings, reducing private investment and consumption. Most relevant near full employment.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'List four UK fiscal rules used in recent years.', 'Current (2026) rules: the stability rule (current budget in balance or surplus by a set forecast year) and the investment rule (public sector net financial liabilities falling as a share of GDP by year five). Earlier rules used cyclically-adjusted balances, a debt/GDP target and a welfare cap. Specific rules change with government.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Define supply-side policies.', 'Policies designed to raise the productive capacity (LRAS) and improve the long-run growth rate by improving the quantity or quality of factors of production and the efficiency of markets.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Distinguish market-based and interventionist supply-side policies.', 'Market-based: free up markets — cut income/corporation tax, deregulation, privatisation, lower trade-union power. Interventionist: government action — infrastructure, education, R&D subsidies, training schemes.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Give three benefits and two costs of supply-side policies.', 'Benefits: higher non-inflationary growth, lower structural unemployment, better trade balance. Costs: long time lags, regressive income effects of tax cuts, potential to worsen inequality, fiscal cost.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the Laffer curve?', 'A graph showing tax revenue against tax rate. Revenue rises then falls as the rate rises beyond an optimum, because high rates discourage work, encourage avoidance and shrink the tax base. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 130 Q115 0 200 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="115" y1="130" x2="115" y2="60" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><circle cx="115" cy="60" r="2.5" fill="#0B1E3F"/><text x="115" y="55" font-size="8" fill="#0B1E3F" text-anchor="middle">t*</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">Revenue</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Tax rate</text></svg>', 14),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Why might monetary and fiscal policy need to be coordinated?', 'They influence AD jointly. A loose fiscal stance combined with tight monetary policy creates conflicting signals, raising long-term rates and worsening the policy mix; coordination improves outcomes.', 15),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Explain the Office for Budget Responsibility (OBR).', 'An independent UK body created in 2010 that produces official forecasts of growth, inflation and the public finances, and judges whether the government is meeting its fiscal rules.', 16),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Define globalisation and give four of its characteristics.', 'The increasing integration and interdependence of national economies. Characteristics: rising trade as a share of world GDP; fragmented global supply chains; growing flows of foreign direct investment; increased migration of labour; integrated financial markets; convergence of consumer tastes; growing influence of MNCs and bodies such as the WTO.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'List the main causes of globalisation.', 'Falling transport costs (containerisation, cheap air freight); falling communication and IT costs (internet, cloud); trade liberalisation through GATT/WTO and regional agreements; deregulation of financial markets and removal of capital controls (UK 1979); the opening of China (reforms from 1978, WTO accession 2001) and the collapse of the Soviet bloc; the growth of MNCs building global supply chains.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Why do firms become multinational, and what are the costs to a host country?', 'Motives: lower labour, land or raw material costs; market access and tariff jumping; economies of scale; access to raw materials; lighter regulation and tax. Costs to the host: profits repatriated (a debit on primary income); local firms driven out by monopoly/monopsony power; environmental damage and poor conditions where regulation is weak; transfer pricing means little tax is paid; footloose capital can relocate at short notice.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Distinguish absolute advantage from comparative advantage.', 'Absolute advantage: a country can produce more of a good than another using the same resources. Comparative advantage: a country can produce a good at a lower opportunity cost than another. Ricardo (1817) showed that trade is mutually beneficial whenever opportunity costs differ, even if one country has an absolute advantage in everything. If the opportunity cost ratios are identical, there is no comparative advantage and no gain from trade.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Country A can make 200 machines or 400 textiles; Country B can make 100 machines or 300 textiles. Who has the comparative advantage in each good, and what are the acceptable terms of trade?', 'A: 1 machine costs 2 textiles; B: 1 machine costs 3 textiles, so A has the comparative advantage in machines. B: 1 textile costs 0.33 machines; A: 1 textile costs 0.5 machines, so B has the comparative advantage in textiles (even though A has an absolute advantage in both). Mutually beneficial terms of trade lie between 1 machine = 2 textiles and 1 machine = 3 textiles.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Give five limiting assumptions of the theory of comparative advantage.', 'Constant opportunity costs and constant returns to scale (straight-line PPFs); zero transport costs; no trade barriers; perfect factor mobility within countries, so adjustment costs and structural unemployment are ignored; factors assumed immobile between countries, yet capital and labour are now highly mobile; only two countries and two homogeneous goods, so intra-industry trade is unexplained. Also note the risk of over-specialisation and, for primary exporters, the Prebisch-Singer hypothesis of a long-run deterioration in the terms of trade.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Name the instruments of protection and say how the terms of trade are calculated.', 'Tariff (a tax on imports, specific or ad valorem); quota (a physical limit on import volume); subsidy to domestic producers (shifts domestic supply right without raising the consumer price); non-tariff barriers (standards, rules of origin, SPS checks, customs paperwork); embargo (a complete ban); and exchange rate manipulation. Terms of trade = (index of export prices / index of import prices) x 100.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'On a tariff diagram, what are the four welfare areas?', 'Price rises from Pw to Pw+T. Consumers lose surplus equal to a+b+c+d. Area a is the gain in producer surplus; area c is government tariff revenue (tariff x imports after the tariff); both are transfers, not net gains. Areas b and d are the production and consumption deadweight losses, so the net welfare effect is -(b+d). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><rect x="103" y="85" width="24" height="15" fill="#0B1E3F" fill-opacity="0.18"/><line x1="45" y1="120" x2="185" y2="35" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="35" x2="185" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="100" x2="198" y2="100" stroke="#0B1E3F" stroke-width="1"/><line x1="30" y1="85" x2="198" y2="85" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><text x="188" y="33" font-size="8" fill="#0B1E3F">S</text><text x="188" y="122" font-size="8" fill="#0B1E3F">D</text><text x="28" y="103" font-size="8" fill="#0B1E3F" text-anchor="end">Pw</text><text x="28" y="88" font-size="8" fill="#0B1E3F" text-anchor="end">Pw+T</text><text x="113" y="96" font-size="8" fill="#0B1E3F" text-anchor="middle">c</text><text x="205" y="145" font-size="8" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 8),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Give the main arguments for and against protectionism.', 'For: the infant industry argument; protecting employment and preventing structural unemployment; preventing dumping (anti-dumping duties are permitted by WTO rules); correcting a current account deficit; strategic, food and national security; raising government revenue; preventing a race to the bottom on environmental and labour standards. Against: higher prices and a regressive hit to consumers; misallocation of resources (deadweight loss); X-inefficiency from reduced competition; higher input costs for downstream firms; retaliation and trade wars; damage to developing-country exporters.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Set out the structure of the balance of payments and the recent UK position.', 'Current account: trade in goods, trade in services, primary income (cross-border wages and investment income), secondary income (transfers such as aid and remittances). Capital account: capital transfers and non-produced, non-financial assets. Financial account: FDI, portfolio investment, other investment, reserve assets. The accounts sum to zero. UK: the underlying current account deficit excluding precious metals was £15.1bn, or 1.9% of GDP, in Q2 2026, down from £18.2bn (2.4% of GDP) in Q1 2026; the 2025 deficit was 2.4% of GDP against 2.8% in 2024. In 2025 a £221bn goods deficit was partly offset by a £203bn services surplus.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What causes a current account deficit, and what policies can correct one?', 'Cyclical causes: strong domestic growth pulling in imports; recession in export markets; a temporarily strong exchange rate; a spike in world commodity prices. Structural causes: low productivity and high relative unit labour costs; weak non-price competitiveness; deindustrialisation; low investment; North Sea depletion; foreign ownership of domestic assets weakening primary income. Policies: expenditure-reducing (contractionary fiscal/monetary policy); expenditure-switching (depreciation); protectionism (risks retaliation); supply-side policy, which tackles the structural cause but works only over many years.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Compare floating, fixed and managed exchange rate systems.', 'Floating: set purely by demand for and supply of the currency (the UK since leaving the ERM in September 1992). Gives automatic current account adjustment, needs no reserves and frees monetary policy, but is volatile and can import inflation. Fixed: the central bank defends a declared value using reserves and interest rates (Bretton Woods 1944-71). Gives certainty and inflation discipline, but needs large reserves, subordinates monetary policy and invites speculative attack. Managed (dirty) float: mostly market-determined with official intervention to smooth movements. The impossible trinity: a country can have only two of free capital movement, a fixed rate and independent monetary policy.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'State the Marshall-Lerner condition and explain competitive devaluation.', 'Marshall-Lerner: a depreciation improves the current account only if PED(exports) + PED(imports) > 1. If the sum is below 1, demand is inelastic, import volumes barely fall while each import costs more, and the balance worsens. Competitive devaluation is a deliberate reduction in the exchange rate to gain a trade advantage; it is a beggar-my-neighbour policy that works only if partners do not retaliate. If several devalue together, relative rates are unchanged, nothing is gained and global inflation rises, as in the 1930s.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'Explain the J-curve effect.', 'After a depreciation the current account first worsens and only later improves. Immediately, import prices in sterling rise while contracted volumes are unchanged, so the import bill rises: short-run elasticities are low and Marshall-Lerner is not met. Over time foreign buyers switch to cheaper exports, domestic buyers substitute away from dearer imports and exporters add capacity, so elasticities rise, Marshall-Lerner is satisfied and the balance improves. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="30" y1="75" x2="200" y2="75" stroke="#0B1E3F" stroke-width="0.6" stroke-dasharray="3 2"/><line x1="60" y1="28" x2="60" y2="130" stroke="#0B1E3F" stroke-width="0.6" stroke-dasharray="3 2"/><path d="M45 75 L60 75 C72 95 85 108 98 110 C118 113 135 98 148 75 C162 50 180 38 198 32" fill="none" stroke="#0B1E3F" stroke-width="1.8"/><text x="28" y="78" font-size="8" fill="#0B1E3F" text-anchor="end">0</text><text x="63" y="25" font-size="7" fill="#0B1E3F">depreciation</text><text x="28" y="18" font-size="8" fill="#0B1E3F" text-anchor="end">CA</text><text x="205" y="145" font-size="8" fill="#0B1E3F" text-anchor="end">Time</text></svg>', 14),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'List the stages of economic integration and distinguish trade creation from trade diversion.', 'Free trade area (no internal tariffs, separate external tariffs, so rules of origin are needed); customs union (adds a common external tariff); single market (adds free movement of goods, services, capital and labour plus harmonised regulation); monetary union (adds a single currency and central bank); full economic union (adds fiscal harmonisation). Trade creation: production shifts from a higher-cost domestic producer to a lower-cost partner, raising welfare. Trade diversion: the common external tariff shifts production from a lower-cost non-member to a higher-cost member, lowering welfare. A union is beneficial overall only if creation exceeds diversion.', 15),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'How is development measured, and what are the main barriers and strategies?', 'Measures: real GNI per capita (PPP); the HDI (life expectancy, education, GNI per capita, scored 0-1); the Multidimensional Poverty Index; single indicators such as infant mortality, literacy, access to clean water and the Gini coefficient. Barriers: the savings gap; poor infrastructure; weak human capital; primary product dependency (volatile prices, Prebisch-Singer, the resource curse); weak institutions and corruption; debt burden; capital flight and brain drain; rapid population growth; rich-country trade barriers and tariff escalation. Strategies: trade liberalisation and export-led growth; attracting FDI; investment in human capital and infrastructure; aid; debt relief; microfinance; industrial policy and diversification; institutional reform.', 16)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Economics' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

-- Seed backfill: Chemistry|OCR B|alevel
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give the relative charges and masses of proton, neutron, electron.', 'Proton: +1, mass 1. Neutron: 0, mass 1. Electron: -1, mass 1/1836 (~0).', 1),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Define isotopes.', 'Atoms of the same element with the same number of protons but different numbers of neutrons; same chemical properties, different mass.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Describe the four stages of TOF mass spectrometry.', 'Ionisation (electron impact or electrospray), acceleration to constant kinetic energy, ion drift, and detection. m/z is calculated from time of flight.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Explain why first ionisation energy decreases down a group.', 'Atomic radius increases and shielding rises, outweighing the larger nuclear charge, so the outer electron is held less strongly.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give the electron configuration of Cr and Cu.', 'Cr: [Ar] 3d5 4s1; Cu: [Ar] 3d10 4s1. Half-filled and fully-filled d sub-shells are extra stable.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Calculate the mass of NaOH needed for 250 cm3 of 0.100 mol dm^-3 solution.', 'n = c x V = 0.100 x 0.250 = 0.025 mol. m = n x M_r = 0.025 x 40 = 1.00 g.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'State Avogadro''s constant and use it to find molecules in 0.5 mol H2O.', '6.02 x 10^23 mol^-1. 0.5 mol = 3.01 x 10^23 molecules.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'How does VSEPR predict shape?', 'Electron pairs around a central atom repel each other and arrange to minimise repulsion. Lone pairs repel more than bonding pairs, distorting bond angles.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Sketch the bent shape of H2O and give bond angle.', 'Bent (V-shaped); H-O-H = 104.5 degrees. <svg viewBox="0 0 120 80" width="110" height="75" style="display:block;margin:6px auto"><circle cx="60" cy="30" r="6" fill="#FFFFFF" stroke="#0B1E3F" stroke-width="2"/><text x="55" y="34" font-size="10" fill="#0B1E3F">O</text><line x1="55" y1="35" x2="25" y2="60" stroke="#0B1E3F" stroke-width="2"/><line x1="65" y1="35" x2="95" y2="60" stroke="#0B1E3F" stroke-width="2"/><text x="15" y="72" font-size="10" fill="#0B1E3F">H</text><text x="95" y="72" font-size="10" fill="#0B1E3F">H</text></svg>', 9),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Why is graphite a good conductor of electricity?', 'Each carbon has three covalent bonds within a layer, leaving one delocalised electron per atom in the region between the layers; these electrons are free to move along the layers, so graphite conducts parallel to them.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Compare electrical conductivity of NaCl in three states.', 'Solid: no conduction (ions fixed). Molten or aqueous: conducts (ions free to move and carry charge).', 11),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Why does diamond have a very high melting point?', 'Each carbon is covalently bonded to four others in a tetrahedral giant covalent lattice; melting requires breaking strong covalent bonds throughout the structure.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Define nuclear fusion and state the conditions it requires.', 'Two lighter nuclei join to form a heavier nucleus. It needs very high temperature and pressure so the nuclei have enough kinetic energy to overcome the electrostatic repulsion between their positive charges.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'How do you balance a nuclear equation?', 'The mass numbers (top figures) must sum to the same total on both sides, and the atomic numbers (bottom figures) must also sum to the same total. Remember a positron is mass 0, charge +1.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Write the overall equation for hydrogen burning in a star.', '4 (1,1)H -> (4,2)He + 2 positrons. Mass numbers: 4 = 4. Atomic numbers: 4 = 2 + 2(+1).', 15),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Why does fusion in a star stop at iron?', 'Binding energy per nucleon peaks around iron. Fusing nuclei lighter than iron releases energy; fusing heavier ones would absorb it. Elements beyond iron form by neutron capture in supernovae.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'State and explain the trend in reactivity of the Group 2 metals with water.', 'Reactivity increases down the group. Atomic radius and shielding increase, outweighing the greater nuclear charge, so ionisation enthalpies fall and the electrons are lost more easily.', 17),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'State the solubility trends for the Group 2 hydroxides and sulfates.', 'Hydroxides become more soluble down the group (Mg(OH)2 sparingly soluble, Ba(OH)2 soluble). Sulfates become less soluble (MgSO4 soluble, BaSO4 essentially insoluble).', 18),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Explain why thermal stability of the Group 2 carbonates increases down the group.', 'The cation gets larger, so its charge density falls and it polarises the large carbonate ion less. The C-O bond is weakened less, so a higher temperature is needed: MgCO3 at about 540 C, BaCO3 at about 1360 C.', 19),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'How do you test a solution for sulfate ions?', 'Acidify with dilute hydrochloric or nitric acid to remove carbonate, then add barium chloride solution. A white precipitate confirms sulfate: Ba2+ + SO4^2- -> BaSO4.', 20),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'State the order of infrared, visible and ultraviolet radiation by energy.', 'Infrared lowest, then visible, then ultraviolet highest. Higher energy means higher frequency and shorter wavelength.', 21),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give the two equations linking photon energy, frequency and wavelength.', 'E = h x nu and c = nu x lambda, so E = hc/lambda. h = 6.63 x 10^-34 J s; c = 3.00 x 10^8 m s^-1. Convert the wavelength to metres first.', 22),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Explain how an emission line spectrum is produced.', 'Electrons are excited to higher energy levels, then fall back; each drop emits a photon of energy equal to the gap. Only certain gaps exist, so only certain frequencies appear and the spectrum is a set of lines.', 23),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give two similarities and one difference between emission and absorption spectra.', 'Both are line spectra, with the lines in the same positions for a given element and converging at higher frequency. Emission shows coloured lines on black; absorption shows black lines on a coloured background.', 24),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'What does the convergence limit of a spectral series give you?', 'The frequency at which the lines merge corresponds to removing the electron from the atom. E = h x nu gives the energy per atom; multiply by the Avogadro constant for the ionisation enthalpy per mole.', 25),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give the flame colours of Li+, Na+, K+, Ca2+, Ba2+ and Cu2+.', 'Li+ red, Na+ yellow, K+ lilac, Ca2+ orange-red, Ba2+ pale green, Cu2+ blue-green. Clean the wire with concentrated hydrochloric acid first.', 26),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'State the colours of the silver halide precipitates and their solubility in ammonia.', 'AgCl white, dissolves in dilute ammonia. AgBr cream, dissolves only in concentrated ammonia. AgI yellow, insoluble even in concentrated ammonia.', 27),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Give the precipitate colours when NaOH(aq) is added to Cu2+, Fe2+, Fe3+, Al3+ and Zn2+.', 'Cu(OH)2 pale blue; Fe(OH)2 dirty green, going red-brown in air; Fe(OH)3 red-brown; Al(OH)3 and Zn(OH)2 white and both dissolve again in excess NaOH.', 28),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'What did the Geiger-Marsden experiment show?', 'Most alpha particles passed straight through, so the atom is mostly empty space. A very few were deflected through more than 90 degrees, so the positive charge and nearly all the mass sit in a tiny dense nucleus.', 29),
  ('Chemistry', 'OCR B', 'alevel', 'EL', 'Elements of Life', 'Why is a solution acidified before adding silver nitrate or barium chloride?', 'To remove carbonate ions, which would give a white precipitate and a false positive. Use nitric acid before AgNO3 and hydrochloric acid before BaCl2, so you never add the ion you are testing for.', 30),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Define standard conditions for enthalpy.', '100 kPa pressure, 298 K temperature, all substances in their standard states, with solutions at 1 mol dm^-3.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Define standard enthalpy of combustion.', 'The enthalpy change when one mole of a substance is completely burned in oxygen under standard conditions.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Why does coffee-cup calorimetry of combustion underestimate deltaH?', 'Heat losses to surroundings, incomplete combustion, evaporation, non-standard conditions, and heat absorbed by the apparatus reduce the recorded temperature rise.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'State Hess''s Law.', 'The total enthalpy change is independent of the route taken, provided initial and final conditions are the same.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Why is calculated deltaH from mean bond enthalpies approximate?', 'Mean bond enthalpies are averaged across many molecules; actual bond strengths depend on the molecular environment.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'How does a heterogeneous catalyst work?', 'Reactants adsorb onto the catalyst surface (active sites); bonds are weakened, reactants react in the correct orientation, and products desorb. Lowers Ea without being consumed.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Define a homologous series.', 'A series of organic compounds with the same general formula and functional group, differing by CH2, with similar reactions and a smooth trend in physical properties.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Distinguish E/Z isomers using CIP priority.', 'Z: higher-priority groups on the same side of C=C; E: higher-priority groups on opposite sides. Restricted rotation around C=C is the source of isomerism.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Describe the boiling point trend in the alkane homologous series.', 'Boiling point increases with chain length: longer alkanes have more electrons and larger contact surface, so London forces are stronger.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'State the test for an alkene.', 'Decolourisation of bromine water from orange/yellow to colourless via electrophilic addition forming a 1,2-dibromoalkane.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'State Markownikoff''s rule.', 'In HX addition to an unsymmetric alkene, H bonds to the carbon already bearing more H. The major product comes from the more stable (more substituted) carbocation.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'DF', 'Developing Fuels', 'Sketch the addition polymer of propene.', 'Repeat unit -(CH2-CH(CH3))- joined together. <svg viewBox="0 0 200 60" width="180" height="55" style="display:block;margin:6px auto"><line x1="20" y1="30" x2="50" y2="30" stroke="#0B1E3F" stroke-width="2"/><line x1="50" y1="30" x2="80" y2="30" stroke="#0B1E3F" stroke-width="2"/><line x1="80" y1="30" x2="110" y2="30" stroke="#0B1E3F" stroke-width="2"/><line x1="110" y1="30" x2="140" y2="30" stroke="#0B1E3F" stroke-width="2"/><line x1="140" y1="30" x2="170" y2="30" stroke="#0B1E3F" stroke-width="2"/><line x1="50" y1="30" x2="50" y2="15" stroke="#0B1E3F" stroke-width="1.5"/><text x="42" y="12" font-size="10" fill="#0B1E3F">CH3</text><line x1="110" y1="30" x2="110" y2="15" stroke="#0B1E3F" stroke-width="1.5"/><text x="102" y="12" font-size="10" fill="#0B1E3F">CH3</text><text x="180" y="34" font-size="10" fill="#0B1E3F">]n</text></svg>', 12),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Define atom economy and percentage yield.', 'Atom economy = (M_r product / sum of M_r all products) x 100. % yield = (actual moles product / theoretical moles) x 100. Sustainable processes maximise both.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Define dynamic equilibrium.', 'Forward and reverse reactions occur at equal rates in a closed system, so concentrations of all species remain constant.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Define oxidation and reduction in terms of electrons.', 'Oxidation: loss of electrons (oxidation state increases). Reduction: gain of electrons (oxidation state decreases). Mnemonic: OIL RIG.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Assign oxidation states in MnO4-.', 'O = -2; sum = -1; so Mn = -1 - 4(-2) = +7. Permanganate ion has Mn(VII).', 4),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Give the appearance and state of Cl2, Br2 and I2 at room temperature.', 'Chlorine: pale green gas. Bromine: red-brown liquid. Iodine: grey-black solid that sublimes to a purple vapour.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Why do the boiling points of the halogens increase down the group?', 'The molecules are non-polar, so only instantaneous dipole-induced dipole bonds act between them. More electrons down the group means larger induced dipoles and stronger bonds, so more energy is needed to separate the molecules.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Why does oxidising power decrease down Group 17?', 'A halogen gains an electron: X2 + 2e- -> 2X-. Down the group atomic radius and shielding increase, so the nucleus attracts the incoming electron less strongly and the halogen gains electrons less readily.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Give the ionic equation and observation when chlorine is added to potassium iodide solution.', 'Cl2 + 2I- -> 2Cl- + I2. The colourless solution turns brown; shaken with cyclohexane the organic layer is violet.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Give the silver halide test results, including the ammonia step.', 'Acidify with dilute nitric acid, add silver nitrate. AgCl white, dissolves in dilute ammonia. AgBr cream, dissolves only in concentrated ammonia. AgI yellow, insoluble even in concentrated ammonia.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'What happens when concentrated sulfuric acid is added to solid sodium bromide?', 'NaBr + H2SO4 -> NaHSO4 + HBr, then 2HBr + H2SO4 -> Br2 + SO2 + 2H2O. Steamy fumes, orange-brown bromine vapour and choking SO2. Sulfur goes from +6 to +4.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'What happens when concentrated sulfuric acid is added to solid sodium iodide?', 'NaI + H2SO4 -> NaHSO4 + HI, then 8HI + H2SO4 -> 4I2 + H2S + 4H2O. Purple vapour, a black solid, yellow sulfur and a bad-egg smell. Sulfur goes from +6 to -2.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Which acid is used to prepare HBr and HI, and why?', 'Phosphoric acid. It is not an oxidising agent, so the hydrogen halide is not oxidised to the halogen as it would be by concentrated sulfuric acid.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Give the half-equations for the electrolysis of molten sodium chloride.', 'Cathode (reduction): Na+ + e- -> Na. Anode (oxidation): 2Cl- -> Cl2 + 2e-.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'State the rules for the products of electrolysing an aqueous solution.', 'Cathode: Group 1, Group 2 and aluminium salts give hydrogen from water (2H2O + 2e- -> H2 + 2OH-); any other metal is plated. Anode: a halide ion gives the halogen; otherwise oxygen from water (2H2O -> O2 + 4H+ + 4e-).', 14),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Name the three products of electrolysing brine and give the half-equations.', 'Chlorine, hydrogen and sodium hydroxide. Anode: 2Cl- -> Cl2 + 2e-. Cathode: 2H2O + 2e- -> H2 + 2OH-. A membrane keeps the chlorine and hydroxide apart.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Write the iodine-thiosulfate titration equation and describe the end point.', 'I2 + 2S2O3^2- -> 2I- + S4O6^2-. Titrate until the brown colour fades to pale straw, then add starch (blue-black) and finish dropwise until colourless.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Write the general expression for Kc.', 'For aA + bB <=> cC + dD, Kc = [C]^c[D]^d / ([A]^a[B]^b), using equilibrium concentrations in mol dm^-3. Kc is fixed at a given temperature.', 17),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'What does the magnitude of Kc tell you?', 'Kc >> 1 means the equilibrium lies far to the right and products dominate. Kc << 1 means it lies far to the left. Kc near 1 means neither side is favoured.', 18),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Use Kc to explain the effect of raising a reactant concentration.', 'The bottom of the expression grows, so the top must grow too to keep Kc at the same value. Product concentrations therefore rise and the position of equilibrium moves to the right.', 19),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Define atom economy and give the formula.', 'The proportion of the reactant mass that ends up in the desired product. Atom economy = (Mr of the desired product / total Mr of all products) x 100%.', 20),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Contrast atom economy with percentage yield.', 'Yield measures how much of the theoretical maximum was actually obtained, and better technique improves it. Atom economy is fixed by the balanced equation and can only be changed by choosing a different reaction.', 21),
  ('Chemistry', 'OCR B', 'alevel', 'ES', 'Elements from the Sea', 'Compare the atom economies of the two routes to hydrogen chloride.', 'H2 + Cl2 -> 2HCl has only one product, so 100%. NaCl + H2SO4 -> NaHSO4 + HCl gives 36.5/156.6 = 23.3%, because most of the mass leaves as sodium hydrogensulfate.', 22),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'List the three intermolecular forces from weakest to strongest.', 'London (induced dipole-dipole) < permanent dipole-dipole < hydrogen bonding.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Why is H-bonding only between H and N, O or F?', 'These elements are highly electronegative and small; the H-X bond is very polar and the lone pair on X is concentrated, allowing strong H-bond formation.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Sketch the Maxwell-Boltzmann distribution and label area > Ea.', 'Skewed curve; only molecules with E >= Ea (right tail shaded) can react. <svg viewBox="0 0 200 120" width="180" height="110" style="display:block;margin:6px auto"><line x1="20" y1="100" x2="190" y2="100" stroke="#0B1E3F" stroke-width="1.5"/><line x1="20" y1="100" x2="20" y2="15" stroke="#0B1E3F" stroke-width="1.5"/><path d="M20,100 Q60,15 100,55 T190,98" fill="none" stroke="#0B1E3F" stroke-width="2"/><line x1="130" y1="100" x2="130" y2="20" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3,2"/><text x="120" y="14" font-size="9" fill="#0B1E3F">Ea</text></svg>', 3),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Why does a small temperature rise greatly increase rate?', 'Exponential dependence in Arrhenius: a small increase in T greatly increases the fraction of molecules with E >= Ea, so successful collision rate rises sharply.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Give the propagation steps for the chlorination of methane.', 'Cl. + CH4 -> HCl + CH3.; CH3. + Cl2 -> CH3Cl + Cl. Cl. is regenerated, propagating the chain.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Compare SN1 and SN2.', 'SN2: one-step concerted, rate = k[RX][Nu], inversion, primary halogenoalkanes. SN1: two-step via carbocation, rate = k[RX], racemisation, tertiary halogenoalkanes.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Why does C-I react faster than C-Cl in nucleophilic substitution?', 'C-I has the lowest bond enthalpy and breaks most easily; bond strength dominates over polarity in determining rate.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Distinguish substitution from elimination using KOH.', 'Aqueous KOH: nucleophilic substitution -> alcohol. Ethanolic KOH: elimination -> alkene + water + KX.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Define a radical and distinguish homolytic from heterolytic fission.', 'A radical has an unpaired electron. Homolytic fission gives one electron to each atom, forming two radicals (half curly arrows). Heterolytic fission gives both electrons to one atom, forming two ions (full curly arrows).', 9),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Give the three stages of the radical chain reaction of methane with chlorine.', 'Initiation: Cl2 -> 2Cl. Propagation: Cl. + CH4 -> .CH3 + HCl, then .CH3 + Cl2 -> CH3Cl + Cl. Termination: any two radicals combining, e.g. Cl. + Cl. -> Cl2.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'How do you tell a propagation step from initiation or termination?', 'A propagation step has a radical on both sides. Initiation creates radicals where there were none; termination consumes radicals and creates none.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Write the four reactions that hold stratospheric ozone in a steady state.', 'O2 + UV -> 2O. ; O. + O2 -> O3 ; O3 + UV -> O2 + O. ; O. + O3 -> 2O2. The first two make ozone, the last two destroy it.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Why does a CFC release a chlorine radical rather than a fluorine radical?', 'The C-Cl bond enthalpy is about 346 kJ mol^-1 and C-F about 467 kJ mol^-1. Stratospheric UV has enough energy to break C-Cl but not C-F: CCl2F2 -> .CClF2 + .Cl', 13),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Write the catalytic cycle by which chlorine radicals destroy ozone.', '.Cl + O3 -> .ClO + O2, then .ClO + O. -> .Cl + O2. Overall O3 + O. -> 2O2. The chlorine radical is regenerated, so it is a homogeneous catalyst and .ClO is the intermediate.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Why is ozone beneficial in the stratosphere but harmful in the troposphere?', 'In the stratosphere it absorbs UV-B, which oxygen does not, protecting DNA from damage. At ground level it is a toxic irritant that inflames the lungs and damages crops, formed in photochemical smog from nitrogen oxides and unburnt hydrocarbons.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'OZ', 'The Ozone Story', 'Compare CFCs, HCFCs and HFCs as refrigerants.', 'CFCs are so unreactive they reach the stratosphere and release Cl radicals. HCFCs contain C-H, attacked by hydroxyl radicals in the troposphere, so less survives. HFCs contain no chlorine, so no ozone depletion, but they are potent greenhouse gases.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'How are primary, secondary and tertiary alcohols classified?', 'By the number of carbons attached to the C bonded to OH: 1 = primary, 2 = secondary, 3 = tertiary.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Reagents to oxidise primary alcohol to aldehyde and to carboxylic acid.', 'Aldehyde: K2Cr2O7/H2SO4, distil out as it forms. Carboxylic acid: K2Cr2O7/H2SO4, heat under reflux with excess oxidant.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'State the conditions for esterification.', 'Carboxylic acid + alcohol with concentrated H2SO4 catalyst, heated under reflux: an equilibrium giving an ester + water.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'How is an alcohol converted to a halogenoalkane?', 'React with HX (e.g. NaBr/concentrated H2SO4 generates HBr in situ; or use PCl3/PCl5/SOCl2) to substitute -OH for -X.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Compare reactivity of acyl chlorides and carboxylic acids with alcohols.', 'Acyl chloride + alcohol -> ester + HCl, fast and complete. Carboxylic acid + alcohol -> ester + H2O, slow equilibrium needing H2SO4 catalyst.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Give the M_r and key fragment of butan-2-one (CH3COC2H5).', 'M_r = 72. M+ = 72; alpha-cleavage gives m/z 43 (CH3CO+) and m/z 57 (C2H5CO+); m/z 29 (C2H5+).', 6),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Identify functional group from IR: very broad 2500-3300 cm^-1 + C=O ~1710.', 'Carboxylic acid: broad O-H of acid plus C=O.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Explain how HPLC separates compounds.', 'Sample is forced under high pressure through a column packed with a solid stationary phase; components partition between mobile and stationary phases at different rates, separating by retention time.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Give the atom economy expression and say what it measures.', '% atom economy = (Mr of the desired product / sum of the Mr of all products) x 100. It measures the proportion of the reactant mass that ends up in the wanted product.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Calculate the atom economy of making aspirin (Mr 180) with ethanoic anhydride, by-product ethanoic acid (Mr 60).', '180 / (180 + 60) x 100 = 75.0%.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Why is ethanoic anhydride used to make aspirin rather than ethanoyl chloride?', 'Ethanoyl chloride gives a higher atom economy (83.1%) but reacts violently with water and produces corrosive HCl gas. The anhydride is cheaper, safer to handle, and its ethanoic acid by-product can be recovered and reused.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Name four themes of green chemistry.', 'Prevent waste and maximise atom economy; avoid hazardous reagents and solvents; minimise energy by working near ambient conditions; use renewable feedstocks and catalytic rather than stoichiometric reagents.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Why does a high percentage yield not by itself mean a process is green?', 'Yield only compares the product isolated with the theoretical maximum for that route. A route can give 100% yield and still waste most of its atoms, use hazardous solvents or demand a large energy input.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Define a phenol and give the formula of the simplest one.', 'A compound with an -OH group bonded directly to a carbon of a benzene ring. The simplest is phenol, C6H5OH. In phenylmethanol the -OH sits on a CH2 group, so that is an ordinary alcohol.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Explain why phenol is a stronger acid than ethanol.', 'A lone pair on the phenoxide oxygen overlaps with the delocalised ring, spreading the negative charge and stabilising the ion, so the equilibrium releasing H+ lies further right. The ethoxide charge stays on one oxygen.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'How do phenols react with alkalis and with carbonates?', 'Phenol reacts with NaOH to give sodium phenoxide and water, but does not react with carbonates at all. Carboxylic acids react with both, effervescing with carbonates.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Give the test for a phenol and its result.', 'Add neutral iron(III) chloride solution: a phenol gives an intense purple colouration. Alcohols and carboxylic acids give no purple colour.', 17),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Why must a phenol be esterified with an acid anhydride?', 'Its oxygen lone pair is delocalised into the ring, so a phenol is too poor a nucleophile to react with a carboxylic acid. An anhydride is reactive enough: C6H5OH + (CH3CO)2O -> CH3COOC6H5 + CH3COOH.', 18),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'Write the equation for the synthesis of aspirin.', 'HOC6H4COOH + (CH3CO)2O -> CH3COOC6H4COOH + CH3COOH. The phenol -OH is esterified and the -COOH group is left untouched.', 19),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'How would you distinguish phenol from benzoic acid?', 'Add sodium carbonate solution. Benzoic acid effervesces as CO2 is released; phenol does not react, because it is too weak an acid to displace CO2 from a carbonate.', 20),
  ('Chemistry', 'OCR B', 'alevel', 'WM', 'What''s in a Medicine?', 'How does iron(III) chloride check the purity of aspirin?', 'Pure aspirin has no free phenol group, so it gives no purple colour. A purple tinge shows that unreacted salicylic acid is still present and the crystals need recrystallising.', 21),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the units of k for a second-order reaction.', 'mol^-1 dm^3 s^-1.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'State the linear form of the Arrhenius equation.', 'ln k = -Ea/(RT) + ln A. Plot ln k vs 1/T: gradient = -Ea/R, intercept = ln A.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'State Le Chatelier''s principle.', 'When a system at equilibrium is disturbed by a change in conditions, the position of equilibrium shifts to oppose the change.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'How does increasing pressure affect 2NO2 <=> N2O4?', 'Equilibrium shifts to fewer moles of gas (right, towards N2O4); the colour fades from brown to lighter as more colourless N2O4 forms.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Why does a catalyst not change the equilibrium yield?', 'It speeds up the forward and reverse reactions equally, so equilibrium is reached faster but the position and Kc are unchanged.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Write Kp for N2(g) + 3H2(g) <=> 2NH3(g).', 'Kp = (p(NH3))^2 / (p(N2) x (p(H2))^3). Units depend on pressure unit (e.g. Pa^-2 or atm^-2).', 6),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Describe the bonding in N2 and explain why nitrogen is so unreactive.', 'A triple bond, one sigma and two pi, with a bond enthalpy of 945 kJ mol^-1, plus a lone pair on each atom. Breaking it gives a very large activation enthalpy, so nitrogen reacts extremely slowly.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the shapes and bond angles of NH3 and NH4+.', 'NH3 is pyramidal at 107 degrees: three bond pairs and one lone pair, which repels more strongly. NH4+ is tetrahedral at 109.5 degrees, the dative covalent bond being identical to the other three.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Name the three oxides of nitrogen and give their appearances.', 'N2O dinitrogen oxide, a colourless gas. NO nitrogen monoxide, colourless but turning brown in air. NO2 nitrogen dioxide, a brown toxic gas.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the oxidation state of N in NH4+, N2, N2O, NO, NO2-, NO2 and NO3-.', '-3, 0, +1, +2, +3, +4 and +5 respectively. NO2- is nitrate(III) and NO3- is nitrate(V).', 10),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Describe the tests for ammonium and nitrate(V) ions.', 'Ammonium: warm with NaOH; ammonia is evolved and turns damp red litmus blue. Nitrate(V): warm with NaOH and Devarda''s alloy; ammonia again. Test for ammonium first, or the result is ambiguous.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the units of k for reactions of overall order 0, 1, 2 and 3.', 'mol dm^-3 s^-1; s^-1; mol^-1 dm^3 s^-1; mol^-2 dm^6 s^-1. Each step up in order removes one power of mol and adds three of dm.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'How do successive half-lives identify the order of a reaction?', 'A constant half-life means first order. Half-lives that halve each time mean zero order; half-lives that double each time mean second order.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Link the rate constant to the half-life of a first-order reaction.', 'k = ln 2 / t(half) = 0.693 / t(half), with k in s^-1 when the half-life is in seconds.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'How do you work out the units of Kc?', 'Put mol dm^-3 in place of every concentration and cancel. The power of (mol dm^-3) left is the number of moles on the product side minus the number on the reactant side; equal totals mean no units.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Define partial pressure and mole fraction.', 'Mole fraction x is the moles of that gas divided by the total moles of gas. Partial pressure p = x times the total pressure. The partial pressures add up to the total pressure.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the three stages of the Ostwald process.', '4NH3 + 5O2 -> 4NO + 6H2O over Pt/Rh gauze at about 900 C; then, after cooling, 2NO + O2 <=> 2NO2; then 3NO2 + H2O -> 2HNO3 + NO in an absorption tower, with the NO recycled.', 17),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Give the conditions and catalyst for the Contact process.', 'V2O5 catalyst, about 450 C, only 1-2 atm. 2SO2 + O2 <=> 2SO3, deltaH = -196 kJ mol^-1. Conversion already exceeds 99% at low pressure, so compression is not worth its cost.', 18),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Why is SO3 absorbed into concentrated H2SO4 rather than into water?', 'The direct reaction with water is so exothermic that it forms an uncontrollable acid mist. Instead SO3 + H2SO4 -> H2S2O7 (oleum), then H2S2O7 + H2O -> 2H2SO4.', 19),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'How is ethanoic acid made industrially, and what is its atom economy?', 'By carbonylation of methanol: CH3OH + CO -> CH3COOH, over a rhodium or iridium catalyst with an iodomethane promoter at about 150-200 C and 30-40 atm. There is one product, so 100%.', 20),
  ('Chemistry', 'OCR B', 'alevel', 'CI', 'The Chemical Industry', 'Distinguish a hazard from a risk.', 'A hazard is the potential of a substance or situation to cause harm. Risk is how likely that harm actually is, and depends on the quantity involved and on the control measures in place.', 21),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Define a chiral centre.', 'A carbon atom with four different groups attached, giving rise to two non-superimposable mirror-image enantiomers.', 1),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why are aromatic amines weaker bases than aliphatic amines?', 'In phenylamine the N lone pair delocalises into the ring, reducing its availability to accept H+. Alkyl groups in aliphatic amines push electron density onto N, enhancing basicity.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Define an amino acid zwitterion.', 'A dipolar form of an amino acid with -NH3+ and -COO-, no overall charge, formed at the isoelectric point.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Compare addition and condensation polymers.', 'Addition: monomers contain C=C; no by-product, e.g. poly(ethene). Condensation: two functional groups react with loss of a small molecule (H2O or HCl), e.g. polyesters and polyamides.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'How many 1H NMR signals does ethanol show after a D2O shake?', 'Two: CH3 and CH2. The OH proton exchanges with D and disappears.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'State the n+1 rule for 1H NMR splitting.', 'A signal is split into n+1 peaks by the n hydrogen atoms on the adjacent carbon atoms (equivalent to each other); this identifies the number of adjacent H.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What is the role of TMS in NMR?', 'Reference at 0 ppm; gives a single sharp peak, chemically inert, volatile, and contains 12 equivalent H. All other shifts are quoted relative to it.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Name the three components of a nucleotide.', 'A phosphate group, a sugar (deoxyribose in DNA, ribose in RNA) and a nitrogen-containing base. All three are given on the H433 Data Sheet.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why is DNA described as a condensation polymer?', 'Nucleotide monomers join with the loss of a water molecule at each link: phosphate condenses with sugar to build the sugar-phosphate backbone, and each base condenses with a sugar.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Give the DNA base pairs and the number of hydrogen bonds in each.', 'Adenine with thymine, two hydrogen bonds. Cytosine with guanine, three hydrogen bonds. In RNA, uracil replaces thymine.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why is base pairing in DNA specific?', 'Only A-T and C-G place every N-H or O-H donor opposite a lone pair on N or O at the right distance and orientation. A purine always pairs with a pyrimidine, keeping the strands a constant distance apart.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why is hydrogen bonding the right strength for DNA replication?', 'Each bond is weak, so the strands can be unzipped without breaking any covalent bond, yet there are so many that the helix is held firmly. Each separated strand then templates the complementary sequence.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'State two differences between DNA and RNA.', 'DNA has deoxyribose, uses thymine and is a double helix. RNA has ribose, uses uracil and is usually a single strand.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What is the active site of an enzyme, and which level of structure creates it?', 'The small region where the substrate binds and reacts. Its shape and chemistry come from the tertiary structure, the way the protein chain folds.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Explain the shape of the rate versus substrate concentration curve for an enzyme.', 'At low substrate concentration most active sites are free, so rate is proportional to concentration (first order). At high concentration every site is occupied and the enzyme is saturated, so rate is independent of concentration (zero order).', 15),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Distinguish denaturing from competitive inhibition.', 'Denaturing breaks the intermolecular bonds holding the tertiary structure, so the active site loses its shape; it is usually irreversible. Competitive inhibition blocks an intact active site and can be reversed by adding more substrate.', 16),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Define the term pharmacophore.', 'The part of a drug molecule responsible for its biological activity, the atoms that interact with the receptor site. Other groups modify how strongly it binds, how soluble it is and how long it survives in the body.', 17),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Define chiral centre and enantiomers.', 'A chiral centre is a carbon atom bonded to four different atoms or groups. Enantiomers are the two non-superimposable mirror-image forms of such a molecule.', 18),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Which amino acid found in proteins is not chiral, and why?', 'Glycine. Its side chain is a hydrogen atom, so the central carbon carries two hydrogens and therefore only three different groups.', 19),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'How do enantiomers differ, and how are they the same?', 'They rotate plane-polarised light by equal amounts in opposite directions, and behave differently towards other chiral molecules such as enzymes. Melting point, boiling point, density and reactions with achiral reagents are identical.', 20),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'How should a pair of optical isomers be drawn?', 'Use wedge and dash: two plain bonds in the plane of the paper, one bold wedge coming forwards and one dashed bond going back. Draw a mirror line and reflect every group for the second isomer.', 21),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What is a racemic mixture and what does it do to polarised light?', 'An equal mixture of the two enantiomers. The opposite rotations cancel exactly, so there is no net rotation. Synthesis from achiral starting materials always gives a racemate.', 22),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why does chirality matter in medicines?', 'Receptors and enzymes are built from L-amino acids and are themselves chiral, so only one enantiomer fits the active site. The other may be inactive or harmful, as with thalidomide.', 23),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What is the difference between the nominal mass and the precise relative isotopic mass of an ion?', 'Nominal mass uses whole numbers (H 1, C 12, N 14, O 16). The precise mass is measured against 12C = 12.000000 exactly and is quoted to several decimal places, so no other isotope comes out as a whole number.', 24),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Give the precise relative isotopic masses of 1H, 12C, 14N and 16O.', '1H = 1.007825, 12C = 12.000000 (exact, by definition), 14N = 14.003074, 16O = 15.994915.', 25),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Four species share the nominal m/z of 28. Give their precise masses.', 'CO+ 27.9949, N2+ 28.0061, CH2N+ 28.0187, C2H4+ 28.0313. A low-resolution spectrum shows one peak at 28; a high-resolution one separates all four.', 26),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'How is a high-resolution M+ value used to find a molecular formula?', 'Add the precise isotopic masses for every candidate formula of that nominal mass and keep the one that matches. M+ = 88.0524 is C4H8O2 (48.000000 + 8.062600 + 31.989830), not C3H4O3 (88.0160) or C5H12O (88.0888).', 27),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why does a precise mass drift above or below the nominal mass?', 'Each H sits about 0.0078 above nominal and each N about 0.0031 above, while each O sits about 0.0051 below. The offsets do not cancel, so formulae sharing a nominal mass end up measurably apart.', 28),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'In what order should combined mass spectrum, IR and NMR data be worked through?', 'Molecular formula from M+, then functional groups from the IR including the absences, then carbon environments from 13C NMR, then shift, integration and splitting from 1H NMR. Assemble a structure, then test it against every piece of data.', 29),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What does the absence of an infrared absorption tell you?', 'Nothing broad at 2500-3300 cm^-1 rules out a carboxylic acid. Nothing at 3200-3600 cm^-1 rules out an alcohol or phenol. Nothing at 1620-1680 cm^-1 rules out C=C. Absences earn marks as readily as presences.', 30),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'How do the 1H NMR spectra of ethyl ethanoate and methyl propanoate differ?', 'Both give a 2H quartet, a 3H singlet and a 3H triplet. In ethyl ethanoate the quartet is on the oxygen at about delta 4.1 and the singlet is at about delta 2.0. In methyl propanoate the OCH3 singlet is at about delta 3.7 and the quartet, next to C=O, at about delta 2.3.', 31),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What holds the primary structure of a protein together?', 'The primary structure is the sequence of amino acid residues along the chain, joined by covalent peptide (amide) bonds. Because those bonds are covalent it survives heating; only hydrolysis breaks it.', 32),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What holds the secondary structure of a protein together, and what are its two forms?', 'Hydrogen bonds between the C=O of one peptide link and the N-H of another along the backbone. The alpha-helix coils, with each C=O bonded to the N-H four residues further along the same chain and the R groups pointing outwards. The beta-pleated sheet has sections of chain side by side, with the hydrogen bonds running across between them.', 33),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Name the four interactions between R groups that hold a protein tertiary structure.', 'Sulfur-sulfur (disulfide) bridges between two cysteine residues, which are covalent and strongest; ionic attractions between -NH3+ and -COO- side chains; hydrogen bonds between polar side chains; and instantaneous dipole-induced dipole bonds between non-polar side chains.', 34),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why do heat and extreme pH denature a protein, and what survives?', 'Heat breaks the hydrogen bonds, ionic attractions and instantaneous dipole-induced dipole bonds holding the secondary and tertiary structure, so the chain unfolds and the shape is lost. Extreme pH protonates -COO- or deprotonates -NH3+ side chains, destroying the ionic attractions. The covalent peptide bonds and disulfide bridges are unaffected, so the primary structure survives: denaturing is not hydrolysis.', 35),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'Why is a globular protein soluble in water but keratin is not?', 'A globular protein folds with its polar and charged R groups on the outside, hydrogen bonding to water, and its non-polar R groups packed inside, held by instantaneous dipole-induced dipole bonds, so the molecule looks polar to water. Keratin instead packs long chains alongside one another with many hydrogen bonds and disulfide bridges between them, leaving little for water to interact with.', 36),
  ('Chemistry', 'OCR B', 'alevel', 'PL', 'Polymers and Life', 'What do the numbers in nylon-6,6, nylon-6,10 and nylon-6 count?', 'The first digit is the number of carbons in the diamine and the second the number in the dicarboxylic acid, including both carboxyl carbons. Nylon-6,6: 1,6-diaminohexane with hexanedioic acid, repeat unit -[NH(CH2)6NHCO(CH2)4CO]-. Nylon-6,10: 1,6-diaminohexane with decanedioic acid, -[NH(CH2)6NHCO(CH2)8CO]-. A single digit means one monomer carrying both groups, so nylon-6 comes from 6-aminohexanoic acid or caprolactam, -[NH(CH2)5CO]-.', 37),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Sketch a Born-Haber cycle for NaCl.', 'Steps: atomisation of Na, ionisation of Na, atomisation of 1/2Cl2, electron affinity of Cl, lattice formation. Sum equals deltaH_f. <svg viewBox="0 0 200 120" width="180" height="110" style="display:block;margin:6px auto"><line x1="10" y1="100" x2="190" y2="100" stroke="#0B1E3F" stroke-width="1"/><line x1="20" y1="100" x2="20" y2="80" stroke="#0B1E3F" stroke-width="1.5"/><line x1="20" y1="80" x2="60" y2="80" stroke="#0B1E3F" stroke-width="1.5"/><line x1="60" y1="80" x2="60" y2="40" stroke="#0B1E3F" stroke-width="1.5"/><line x1="60" y1="40" x2="100" y2="40" stroke="#0B1E3F" stroke-width="1.5"/><line x1="100" y1="40" x2="100" y2="20" stroke="#0B1E3F" stroke-width="1.5"/><line x1="100" y1="20" x2="140" y2="20" stroke="#0B1E3F" stroke-width="1.5"/><line x1="140" y1="20" x2="140" y2="100" stroke="#0B1E3F" stroke-width="1.5"/><text x="22" y="115" font-size="9" fill="#0B1E3F">Na(s)</text><text x="135" y="115" font-size="9" fill="#0B1E3F">NaCl(s)</text><text x="100" y="14" font-size="8" fill="#0B1E3F">gas ions</text></svg>', 1),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Why is the lattice enthalpy of MgO much larger than NaCl?', 'Mg2+ and O2- have larger charges (2+/2-) and smaller radii, so the electrostatic attraction in the lattice is much stronger.', 2),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Define entropy.', 'A measure of the dispersal of energy in a system; higher entropy = more disorder/ways to arrange particles. Symbol S, units J K^-1 mol^-1.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Predict the sign of deltaS for H2O(l) -> H2O(g).', 'Positive; entropy of gas >> entropy of liquid, so disorder increases significantly.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'State the Gibbs equation and feasibility condition.', 'deltaG = deltaH - T(deltaS); a reaction is thermodynamically feasible when deltaG <= 0.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Define a Bronsted-Lowry acid and base.', 'Acid: proton donor. Base: proton acceptor. e.g. HCl + NH3 -> NH4+ + Cl-: HCl is the acid, NH3 the base.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Calculate pH of 0.020 mol dm^-3 HCl.', 'Strong acid: [H+] = 0.020. pH = -log10(0.020) = 1.70.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Define Ka and pKa.', 'Ka = [H+][A-]/[HA] for HA <=> H+ + A-. pKa = -log10(Ka). Smaller pKa = stronger acid.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Calculate pH of 0.10 mol dm^-3 ethanoic acid (Ka = 1.8 x 10^-5).', '[H+] = sqrt(Ka x [HA]) = sqrt(1.8e-5 x 0.10) ~ 1.34e-3. pH ~ 2.87.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'State the value of Kw at 298 K.', 'Kw = [H+][OH-] = 1.00 x 10^-14 mol^2 dm^-6. In pure water [H+] = [OH-] = 10^-7, pH = 7.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'How does a buffer mixture of CH3COOH and CH3COO- resist added acid?', 'Added H+ + CH3COO- -> CH3COOH; the conjugate base mops up the H+, so [H+] and pH change very little.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'State the Henderson-Hasselbalch equation.', 'pH = pKa + log10([A-]/[HA]). When [A-] = [HA], pH = pKa (the half-equivalence point).', 12),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Sketch a strong acid + weak base titration curve.', 'pH starts low, rises slowly through buffer region, and equivalence point is < 7 (acidic salt). <svg viewBox="0 0 200 120" width="180" height="110" style="display:block;margin:6px auto"><line x1="20" y1="105" x2="190" y2="105" stroke="#0B1E3F" stroke-width="1.5"/><line x1="20" y1="105" x2="20" y2="10" stroke="#0B1E3F" stroke-width="1.5"/><path d="M20,95 L80,80 L100,55 L160,40 L180,38" fill="none" stroke="#0B1E3F" stroke-width="2"/><circle cx="95" cy="65" r="2" fill="#0B1E3F"/><text x="2" y="60" font-size="9" fill="#0B1E3F">pH</text></svg>', 13),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Choose an indicator for HCl + NH3 titration.', 'Methyl orange (pH 3.1-4.4); equivalence pH < 7 because NH4Cl is acidic. Phenolphthalein would change colour too late.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'O', 'Oceans', 'Why is enthalpy of neutralisation less exothermic for a weak acid than a strong acid?', 'Some energy is needed to fully ionise the weak acid before neutralisation, so net heat released per mole of water formed is smaller.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Balance: MnO4- + Fe2+ + H+ -> Mn2+ + Fe3+ + H2O.', 'MnO4- + 8H+ + 5Fe2+ -> Mn2+ + 5Fe3+ + 4H2O. Combine half-equations balancing electrons (5 e- per Mn).', 1),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Define standard electrode potential.', 'The voltage of a half-cell measured against a standard hydrogen electrode under standard conditions (1 mol dm^-3 ions, 100 kPa, 298 K).', 2),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'How is cell EMF calculated?', 'E_cell = E(more positive electrode) - E(more negative electrode). Positive E_cell -> reaction is feasible under standard conditions.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Sketch a galvanic cell with Zn and Cu electrodes.', 'Zn(s) | Zn2+ || Cu2+ | Cu(s); voltmeter between them; salt bridge between solutions. <svg viewBox="0 0 200 100" width="180" height="90" style="display:block;margin:6px auto"><rect x="20" y="40" width="60" height="50" fill="none" stroke="#0B1E3F" stroke-width="1.5"/><rect x="120" y="40" width="60" height="50" fill="none" stroke="#0B1E3F" stroke-width="1.5"/><line x1="50" y1="40" x2="50" y2="20" stroke="#0B1E3F" stroke-width="2"/><line x1="150" y1="40" x2="150" y2="20" stroke="#0B1E3F" stroke-width="2"/><line x1="50" y1="20" x2="150" y2="20" stroke="#0B1E3F" stroke-width="1.5"/><circle cx="100" cy="20" r="6" fill="#FFFFFF" stroke="#0B1E3F" stroke-width="1.5"/><text x="96" y="24" font-size="9" fill="#0B1E3F">V</text><line x1="80" y1="50" x2="120" y2="50" stroke="#0B1E3F" stroke-width="1.5" stroke-dasharray="4,3"/><text x="35" y="98" font-size="9" fill="#0B1E3F">Zn</text><text x="135" y="98" font-size="9" fill="#0B1E3F">Cu</text></svg>', 4),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Why might a feasible reaction not occur?', 'Activation energy may be too high (kinetics), or non-standard conditions shift the actual potential. E_cell is purely thermodynamic.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Outline a hydrogen-oxygen fuel cell.', 'Anode: H2 -> 2H+ + 2e-. Cathode: 1/2 O2 + 2H+ + 2e- -> H2O. Overall: 2H2 + O2 -> 2H2O. EMF ~ 1.23 V; only product water.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Define a transition metal.', 'A d-block element forming at least one stable ion with a partially filled d sub-shell. Sc and Zn are excluded.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'List the four characteristic properties of transition metals.', 'Variable oxidation states; coloured ions; catalytic activity; complex ion formation.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Why are most transition metal complexes coloured?', 'Ligands split d orbitals into two energy levels; electrons absorb visible photons (deltaE = hf) to be promoted, and the complementary colour is transmitted.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Give examples of monodentate, bidentate, and hexadentate ligands.', 'Monodentate: H2O, NH3, Cl-, CN-. Bidentate: ethane-1,2-diamine (en), ethanedioate. Hexadentate: EDTA4-.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Give shape and bond angle of [Cu(H2O)6]2+ and [CuCl4]2-.', '[Cu(H2O)6]2+: octahedral, 90 degrees. [CuCl4]2-: tetrahedral, 109.5 degrees (Cl- too bulky for 6 ligands).', 11),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'Give the colour change for adding excess NH3 to Cu2+(aq).', 'Blue solution -> pale blue ppt of Cu(OH)2(H2O)4 -> deep blue solution of [Cu(NH3)4(H2O)2]2+ in excess ammonia.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'DM', 'Developing Metals', 'How does a colorimeter measure transition metal ion concentration?', 'Calibrate with standards to make a calibration curve of absorbance vs concentration; measure unknown''s absorbance and read off [ion]. Uses the wavelength of maximum absorption.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Describe the structure of benzene.', 'Planar hexagonal ring of 6 sp2 carbons; each contributes one electron to a delocalised pi system above and below the ring. <svg viewBox="0 0 100 100" width="90" height="90" style="display:block;margin:6px auto"><polygon points="50,10 87,30 87,72 50,92 13,72 13,30" fill="none" stroke="#0B1E3F" stroke-width="2"/><circle cx="50" cy="51" r="20" fill="none" stroke="#0B1E3F" stroke-width="1.5"/></svg>', 1),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Why does benzene undergo electrophilic substitution rather than addition?', 'Substitution preserves the delocalised pi system; addition would disrupt it and lose aromatic stability (~152 kJ mol^-1).', 2),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Conditions and electrophile for nitration of benzene.', 'concentrated HNO3 + concentrated H2SO4 at 50 C; the electrophile is NO2+. Product: nitrobenzene.', 3),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Outline the nucleophilic addition of HCN to ethanal.', 'CN- attacks delta+ C of C=O; alkoxide forms; protonation gives a 2-hydroxynitrile (cyanohydrin) as a racemic mixture if a chiral C is created.', 4),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Distinguish aldehydes from ketones with two tests.', '2,4-DNP gives orange/yellow ppt with both. Tollens'' (silver mirror) and Fehling''s (brick-red Cu2O) react only with aldehydes.', 5),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Why are some organic molecules coloured?', 'Absorbing a photon promotes an electron between electronic energy levels. If the gap matches a wavelength of visible light, that colour is removed from white light and the molecule appears the complementary colour.', 6),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'How does the extent of delocalisation affect the light absorbed?', 'A longer delocalised system has energy levels closer together, so a smaller gap, so longer wavelengths are absorbed. Benzene absorbs in the UV and is colourless; beta-carotene with eleven conjugated C=C bonds absorbs blue and looks orange.', 7),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Give the reagents and conditions for making a diazonium salt from phenylamine.', 'Sodium nitrite and hydrochloric acid (nitrous acid generated in situ), below 10 degrees C. Above 10 degrees C the diazonium ion decomposes to phenol and nitrogen.', 8),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Describe the coupling step of an azo dye synthesis.', 'The cold diazonium solution is added to an alkaline solution of a phenol or aromatic amine. The diazonium ion acts as an electrophile, giving an -N=N- azo link that extends the delocalisation across both rings.', 9),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Name the four functional parts of a dye molecule.', 'The chromophore, which absorbs light; groups that modify it and shift the shade; solubilising groups such as -SO3- Na+; and groups that bond the dye to the fibre.', 10),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Rank the ways dyes bond to fibres in order of fastness.', 'Lowest: intermolecular bonds only (direct dyes on cotton). Then ionic bonds (acid and basic dyes on wool and nylon). Highest: covalent bonds (fibre-reactive dyes on cellulose). Mordant dyes use a metal ion bridge.', 11),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'What are fats and oils, chemically?', 'Mixed triesters of propane-1,2,3-triol (glycerol) with long-chain carboxylic acids, formed by condensation with the loss of three water molecules.', 12),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Why is an unsaturated oil a liquid while a saturated fat is a solid?', 'Cis C=C bonds kink the chains so the molecules cannot pack closely. Less contact means weaker instantaneous dipole-induced dipole bonds, so less energy is needed to melt it.', 13),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'What is saponification?', 'Hydrolysis of a fat with hot aqueous alkali, giving glycerol and the sodium salts of the fatty acids (soap). Acid hydrolysis gives the free fatty acids instead.', 14),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Give the equation and reagent for the sulfonation of benzene.', 'C6H6 + H2SO4 -> C6H5SO3H + H2O, using fuming sulfuric acid at about 40 C. The product is benzenesulfonic acid and the electrophile is SO3.', 15),
  ('Chemistry', 'OCR B', 'alevel', 'CD', 'Colour by Design', 'Why do dye molecules so often carry sulfonate groups?', 'The -SO3H group is a strong acid and exists as -SO3- in water. That makes a large, otherwise insoluble dye soluble in the dyebath, and lets it bond ionically to the -NH3+ groups of wool, silk and nylon.', 16)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Chemistry' AND exam_board = 'OCR B' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

-- Seed backfill: Geography|AQA|alevel
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define a system in physical geography and distinguish open from closed.', 'A set of interrelated stores and flows. Open: exchanges both energy and matter with surroundings (drainage basin). Closed: exchanges only energy (the global water cycle and global carbon cycle on Earth).', 1),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'List the four major stores of the global water cycle and approximate %.', 'Oceans (~97%), cryosphere/ice (~2%), groundwater (~0.7%), surface water and atmosphere (<0.1%). Lithosphere holds tiny amounts in rocks.', 2),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Sketch the global water cycle.', 'Solar energy drives evaporation from oceans, vegetation transpires, vapour rises, condenses, precipitates over land and oceans; runoff and groundwater return to the sea. <svg viewBox="0 0 260 160" width="260" height="160" style="display:block;margin:6px auto"><rect x="0" y="120" width="260" height="40" fill="#9CC3E5"/><polygon points="120,120 200,120 220,80 130,80" fill="#A8D08D"/><circle cx="60" cy="35" r="12" fill="#E7E6E6"/><circle cx="80" cy="40" r="14" fill="#E7E6E6"/><circle cx="180" cy="30" r="14" fill="#E7E6E6"/><circle cx="200" cy="35" r="12" fill="#E7E6E6"/><path d="M40 110 Q40 80 60 50" stroke="#0B1E3F" fill="none" stroke-width="1.2" marker-end="url(#a1)"/><path d="M150 90 Q150 70 170 45" stroke="#0B1E3F" fill="none" stroke-width="1.2" marker-end="url(#a1)"/><path d="M210 50 Q220 80 220 110" stroke="#0B1E3F" fill="none" stroke-width="1.2" marker-end="url(#a1)"/><path d="M180 120 L150 130" stroke="#0B1E3F" fill="none" stroke-width="1.2" marker-end="url(#a1)"/><defs><marker id="a1" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#0B1E3F"/></marker></defs><text x="20" y="80" font-size="8" fill="#0B1E3F">evap</text><text x="125" y="65" font-size="8" fill="#0B1E3F">transp</text><text x="220" y="80" font-size="8" fill="#0B1E3F">precip</text><text x="160" y="135" font-size="8" fill="#0B1E3F">runoff</text></svg>', 3),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define a drainage basin and key terms (watershed, source, mouth, confluence).', 'Drainage basin: area of land drained by a river and its tributaries. Watershed: high-ground boundary. Source: where the river begins. Mouth: where it enters the sea. Confluence: junction of two streams.', 4),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Sketch the drainage basin hydrological system (inputs, stores, flows, outputs).', 'Input: precipitation. Stores: interception, surface, soil moisture, groundwater, channel. Flows: surface runoff, throughflow, infiltration, percolation, baseflow. Outputs: evaporation, transpiration, channel discharge. <svg viewBox="0 0 260 160" width="260" height="160" style="display:block;margin:6px auto"><rect x="20" y="20" width="220" height="120" fill="none" stroke="#0B1E3F" stroke-dasharray="3 2"/><line x1="60" y1="20" x2="60" y2="40" stroke="#0B1E3F" stroke-width="1.2" marker-end="url(#a2)"/><text x="62" y="32" font-size="8" fill="#0B1E3F">precip</text><rect x="40" y="50" width="60" height="14" fill="#9CC3E5"/><text x="42" y="61" font-size="8" fill="#0B1E3F">surface</text><rect x="40" y="74" width="60" height="14" fill="#A8D08D"/><text x="42" y="85" font-size="8" fill="#0B1E3F">soil</text><rect x="40" y="98" width="60" height="14" fill="#C9C9C9"/><text x="42" y="109" font-size="8" fill="#0B1E3F">groundwater</text><rect x="160" y="60" width="50" height="14" fill="#9CC3E5"/><text x="163" y="71" font-size="8" fill="#0B1E3F">channel</text><line x1="100" y1="57" x2="160" y2="67" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a2)"/><text x="115" y="55" font-size="7" fill="#0B1E3F">runoff</text><line x1="100" y1="81" x2="160" y2="69" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a2)"/><text x="118" y="78" font-size="7" fill="#0B1E3F">throughflow</text><line x1="100" y1="105" x2="160" y2="73" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a2)"/><text x="120" y="100" font-size="7" fill="#0B1E3F">baseflow</text><line x1="210" y1="67" x2="240" y2="67" stroke="#0B1E3F" stroke-width="1.2" marker-end="url(#a2)"/><text x="215" y="60" font-size="8" fill="#0B1E3F">discharge</text><defs><marker id="a2" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#0B1E3F"/></marker></defs></svg>', 5),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'What is a storm hydrograph and what do its key features mean?', 'A graph of river discharge against time after a storm. Lag time: gap between peak rainfall and peak discharge. Steeper rising limb / shorter lag indicate flashier basin (urbanised, impermeable, steep, saturated). <svg viewBox="0 0 260 160" width="260" height="160" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="245" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><rect x="60" y="100" width="40" height="20" fill="#9CC3E5"/><text x="80" y="95" font-size="8" fill="#0B1E3F" text-anchor="middle">storm</text><path d="M30 125 Q90 125 130 50 Q170 30 210 90 Q230 110 245 120" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="80" y1="100" x2="80" y2="130" stroke="#B00020" stroke-dasharray="2 2"/><line x1="150" y1="38" x2="150" y2="130" stroke="#B00020" stroke-dasharray="2 2"/><line x1="80" y1="140" x2="150" y2="140" stroke="#B00020" stroke-width="1.2" marker-end="url(#a3)"/><text x="115" y="152" font-size="8" fill="#B00020" text-anchor="middle">lag time</text><defs><marker id="a3" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#B00020"/></marker></defs><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">Discharge</text><text x="245" y="148" font-size="9" fill="#0B1E3F" text-anchor="end">time</text></svg>', 6),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Distinguish physical and human factors that increase flood risk.', 'Physical: heavy/prolonged rainfall, snowmelt, impermeable rock, steep relief, antecedent saturation. Human: urbanisation (impermeable surfaces, drains), deforestation, channel modification, climate change.', 7),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'List the four major stores of the global carbon cycle.', 'Lithosphere (sedimentary rocks, fossil fuels — by far the largest), oceans (dissolved CO2, biological carbon), terrestrial biosphere (vegetation, soils), atmosphere (CO2, CH4 — smallest but climate-critical).', 8),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Distinguish fast and slow carbon cycles.', 'Fast: photosynthesis, respiration, decomposition, ocean exchange — operates over days to centuries. Slow: weathering of silicate rocks, sedimentation, volcanism — operates over millions of years.', 9),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Sketch the global carbon cycle (key stores and flows).', 'Atmosphere ↔ photosynthesis (vegetation) and respiration; vegetation → soil via decomposition; oceans absorb/release CO2; weathering removes C; volcanism returns C; fossil fuel combustion releases stored C. <svg viewBox="0 0 280 160" width="280" height="160" style="display:block;margin:6px auto"><rect x="20" y="20" width="240" height="30" fill="#E7E6E6"/><text x="140" y="38" font-size="9" fill="#0B1E3F" text-anchor="middle">Atmosphere (CO2)</text><rect x="20" y="80" width="100" height="30" fill="#A8D08D"/><text x="70" y="98" font-size="9" fill="#0B1E3F" text-anchor="middle">Vegetation</text><rect x="160" y="80" width="100" height="30" fill="#9CC3E5"/><text x="210" y="98" font-size="9" fill="#0B1E3F" text-anchor="middle">Oceans</text><rect x="20" y="125" width="100" height="20" fill="#8B6F47"/><text x="70" y="139" font-size="9" fill="white" text-anchor="middle">Soil/Litho</text><rect x="160" y="125" width="100" height="20" fill="#454545"/><text x="210" y="139" font-size="9" fill="white" text-anchor="middle">Fossil fuels</text><line x1="50" y1="50" x2="50" y2="78" stroke="#0B1E3F" marker-end="url(#a4)"/><text x="35" y="68" font-size="7" fill="#0B1E3F">photo</text><line x1="90" y1="78" x2="90" y2="52" stroke="#0B1E3F" marker-end="url(#a4)"/><text x="92" y="68" font-size="7" fill="#0B1E3F">resp</text><line x1="190" y1="50" x2="190" y2="78" stroke="#0B1E3F" marker-end="url(#a4)"/><line x1="220" y1="78" x2="220" y2="52" stroke="#0B1E3F" marker-end="url(#a4)"/><line x1="70" y1="110" x2="70" y2="123" stroke="#0B1E3F" marker-end="url(#a4)"/><line x1="200" y1="123" x2="200" y2="55" stroke="#B00020" stroke-width="1.2" marker-end="url(#a5)"/><text x="205" y="80" font-size="7" fill="#B00020">combust</text><defs><marker id="a4" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#0B1E3F"/></marker><marker id="a5" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#B00020"/></marker></defs></svg>', 10),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'How are land-use change and farming affecting the carbon cycle?', 'Deforestation releases stored carbon and reduces sinks. Ploughing exposes and oxidises soil organic matter. Drainage of peatlands releases CO2. Livestock and rice paddies emit methane.', 11),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define the water and carbon budgets and explain why they are linked.', 'Water budget = inputs − outputs of water in a system; carbon budget = sources − sinks of C. They are linked because plant productivity (carbon uptake) requires water, and the warming hydrological cycle alters carbon storage (drought, soil moisture).', 12),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Why does the Amazon rainforest matter for both cycles?', 'Stores ~150-200 Pg C in biomass and soils; transpires huge water vapour into the atmosphere driving regional rainfall. Deforestation reduces both the carbon sink and the moisture flux, risking ''dieback'' tipping points.', 13),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Compare positive and negative feedbacks in the climate system.', 'Positive amplifies the original change: ice-albedo (less ice -> more absorbed solar -> more melt), permafrost thaw -> CH4 release. Negative dampens: more CO2 -> more plant growth -> CO2 uptake (limited).', 14),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define dynamic equilibrium and tipping point.', 'Dynamic equilibrium: stores fluctuate around a long-term average as inputs balance outputs. Tipping point: critical threshold where small change causes a shift to a new state, often irreversible (e.g. Atlantic ocean circulation collapse).', 15),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Outline mitigation and adaptation strategies for the carbon cycle.', 'Mitigation: cut emissions (renewables, EVs), carbon capture and storage, afforestation, reduce deforestation (REDD+). Adaptation: flood defences, drought-resistant crops, coastal managed retreat, water resource planning.', 16),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define an aquifer and explain its importance.', 'A permeable rock layer (often porous sandstone or jointed limestone/chalk) saturated with groundwater. Recharged slowly by percolation. The London Basin chalk aquifer has been over-abstracted and is recovering (~3 m/yr) since 1990s.', 17),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'How does the cryosphere influence the global water cycle?', 'Stores ~2% of global water; reflects ~80% of incident solar (high albedo). Melt redistributes water to oceans (sea-level rise) and changes ocean salinity, affecting thermohaline circulation. Permafrost stores frozen organic matter.', 18),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Define the soil moisture budget.', 'Balance of water inputs (precipitation) and outputs (evapotranspiration, drainage) in soil over time. Field capacity reached after rain; deficit develops in summer; recharge in autumn. Critical for agriculture and runoff timing.', 19),
  ('Geography', 'AQA', 'alevel', '1.1', 'Water & Carbon Cycles', 'Explain the ocean biological and physical carbon pumps.', 'Physical (solubility) pump: cold polar water dissolves CO2, sinks, locks C in deep ocean for centuries. Biological pump: phytoplankton photosynthesise; dead matter sinks (''marine snow'') sequestering C in sediments. Slowing as oceans warm.', 20),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Define a sediment cell.', 'A largely self-contained coastal section with sources, transfers and sinks of sediment between fixed boundaries (usually headlands). England and Wales are divided into 11 cells — useful for integrated coastal management.', 1),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Distinguish constructive and destructive waves.', 'Constructive: low height, long wavelength, low frequency (6-8/min), strong swash, weak backwash, builds berms. Destructive: tall, short wavelength, frequent (10-14/min), weak swash, strong backwash, removes sediment. <svg viewBox="0 0 260 140" width="260" height="140" style="display:block;margin:6px auto"><g><line x1="10" y1="100" x2="125" y2="100" stroke="#0B1E3F"/><path d="M10 100 Q30 80 50 100 T90 100 T130 100" stroke="#0B1E3F" fill="none"/><text x="65" y="120" font-size="9" fill="#0B1E3F" text-anchor="middle">Constructive</text></g><g><line x1="135" y1="100" x2="250" y2="100" stroke="#0B1E3F"/><path d="M135 100 Q150 70 165 100 T195 100 T225 100 T255 100" stroke="#0B1E3F" fill="none"/><text x="195" y="120" font-size="9" fill="#0B1E3F" text-anchor="middle">Destructive</text></g></svg>', 2),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Name four wave-driven erosional processes.', 'Hydraulic action (waves compress air in cracks), abrasion/corrasion (sediment scours), attrition (rocks knock together, become rounder), corrosion/solution (chemical dissolving — limestone, chalk).', 3),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Describe longshore drift.', 'Sediment is moved along a coast in a zigzag pattern: swash carries material up the beach in the prevailing wind direction; backwash returns it perpendicular to the shoreline. Net result: lateral transport. <svg viewBox="0 0 260 130" width="260" height="130" style="display:block;margin:6px auto"><rect x="0" y="60" width="260" height="70" fill="#F2D9A5"/><line x1="0" y1="60" x2="260" y2="60" stroke="#0B1E3F" stroke-width="1.2"/><path d="M20 100 L60 70" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)"/><path d="M60 70 L80 100" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)" stroke-dasharray="2 2"/><path d="M80 100 L120 70" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)"/><path d="M120 70 L140 100" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)" stroke-dasharray="2 2"/><path d="M140 100 L180 70" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)"/><path d="M180 70 L200 100" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)" stroke-dasharray="2 2"/><path d="M200 100 L240 70" stroke="#0B1E3F" stroke-width="1" marker-end="url(#a6)"/><path d="M40 30 L80 30" stroke="#B00020" marker-end="url(#a7)"/><text x="60" y="22" font-size="8" fill="#B00020" text-anchor="middle">prevailing wind</text><text x="20" y="125" font-size="8" fill="#0B1E3F">swash → solid; backwash → dashed</text><defs><marker id="a6" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#0B1E3F"/></marker><marker id="a7" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#B00020"/></marker></defs></svg>', 4),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Outline how a wave-cut platform forms.', 'Waves erode a notch at the high-water mark; the cliff above is undercut and collapses; the cliff retreats inland leaving a flat rocky platform exposed at low tide. Continued retreat builds a wider platform.', 5),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Describe the headland-bay-stack-arch sequence.', 'Differential erosion of soft and hard rock creates headlands and bays. Headlands are attacked from sides: cracks → caves → caves meet to form an arch → arch collapses leaving a stack → stack erodes to a stump. <svg viewBox="0 0 280 140" width="280" height="140" style="display:block;margin:6px auto"><polygon points="0,140 0,80 40,80 50,90 80,90 90,80 130,80 130,140" fill="#A0A0A0"/><polygon points="170,140 170,80 200,80 210,95 230,95 240,80 270,80 270,140" fill="#A0A0A0"/><circle cx="220" cy="92" r="8" fill="white"/><polygon points="148,140 148,90 158,90 158,140" fill="#A0A0A0"/><rect x="0" y="100" width="280" height="40" fill="#9CC3E5" fill-opacity="0.6"/><text x="65" y="115" font-size="8" fill="#0B1E3F">headland</text><text x="220" y="80" font-size="8" fill="#0B1E3F" text-anchor="middle">arch</text><text x="153" y="78" font-size="8" fill="#0B1E3F" text-anchor="middle">stack</text></svg>', 6),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'How do beaches form and what controls their profile?', 'Beaches form where constructive waves deposit sediment in sheltered bays and lower-energy stretches. Profile depends on sediment size (steeper for shingle, gentler for sand), wave energy, and tidal range.', 7),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Outline the formation of a spit.', 'Longshore drift transports sediment past a change in coastline orientation; sediment accumulates in deeper water; secondary winds curve the end (recurve). Sheltered area behind develops salt marsh. Examples: Spurn Head, Hurst Castle.', 8),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Distinguish eustatic and isostatic sea-level change.', 'Eustatic: global change in volume of seawater (melting ice, thermal expansion). Isostatic: local change in land level (rebound after deglaciation, subsidence). Together produce relative sea-level change.', 9),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Distinguish emergent and submergent landforms.', 'Emergent (sea fell or land rose): raised beaches, fossil cliffs. Submergent (sea rose or land fell): rias (drowned river valleys), fjords (drowned glacial valleys), Dalmatian coasts.', 10),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'List four hard-engineering coastal defences with one drawback each.', 'Sea wall (expensive, ugly), groynes (starve down-drift coast), rock armour/rip-rap (visual impact), revetment (costly maintenance), gabions (rust over time). All defer the problem rather than solve it.', 11),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'List four soft-engineering coastal defences.', 'Beach nourishment (replenish sand), dune regeneration (planting marram grass), managed retreat/coastal realignment, salt-marsh restoration. Cheaper, more sustainable, but slower-acting.', 12),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Define Shoreline Management Plans (SMPs).', 'UK strategic plans for coastal stretches that select one of four policies for each section: hold the line, advance the line, managed retreat, or no active intervention. Reviewed every 5-10 years.', 13),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Outline the Holderness coastline as a case study.', 'East Yorkshire — fastest eroding coast in Europe (~1.8 m/yr). Boulder clay cliffs, North Sea fetch, longshore drift south. Mappleton groynes (1991) protected village but accelerated erosion at Cowden. Politically contentious.', 14),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'How is climate change altering coasts?', 'Sea-level rise (eustatic + thermal expansion) drowns low-lying coasts; more storms increase erosion; ocean acidification damages coral; warmer oceans bleach reefs; permafrost thaw weakens Arctic coasts.', 15),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'How can a coral reef be a case study of a tropical coastal ecosystem under threat?', 'Great Barrier Reef: warming triggers mass bleaching (1998, 2002, 2016, 2017, 2020, 2022, 2024, 2025 - six events since 2016), acidification slows calcification, agricultural runoff causes COTS outbreaks. 2026 surveys show coral cover starting to recover, but the gap between events is shrinking.', 16),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Outline the formation of sand dunes.', 'Onshore winds blow dry beach sand inland; embryo dunes form around obstacles (driftwood, debris); pioneer species stabilise them (sea couch, then marram); succession runs through yellow and grey (fixed) dunes and damp slacks to dune heath/woodland. Studland (Dorset) and the Sefton coast are UK examples.', 17),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Define a salt marsh and where it forms.', 'Vegetated tidal mudflat in sheltered low-energy environments (estuaries, behind spits). Forms by deposition of fine sediments stabilised by halophytes (Spartina, Salicornia). Stores carbon; buffers storms; nursery for fish.', 18),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Why are mangroves important coastal ecosystems?', 'Mangroves are salt-tolerant trees in tropical/sub-tropical inter-tidal zones. Stilt roots absorb wave energy (~70% reduction). Sequester ~3-5x more carbon per hectare than tropical forest. Threatened by aquaculture and coastal development.', 19),
  ('Geography', 'AQA', 'alevel', '1.2', 'Coastal Systems & Landscapes', 'Outline the formation of an offshore bar and tombolo.', 'Offshore bar: deposition where waves break on shallow seabed, creating a sandbank. Tombolo: depositional ridge linking an island to the mainland (Chesil Beach to Portland; St. Ninian''s Isle, Shetland).', 20),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Define hazard, risk, vulnerability and resilience.', 'Hazard: potential damaging event. Risk: probability × consequence. Vulnerability: degree to which a community is susceptible. Resilience: ability to absorb, adapt and recover. The disaster equation: R = (Hazard × Vulnerability) / Capacity.', 1),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline Park''s hazard response (disaster) curve.', 'Quality of life trace through pre-disaster, disruption, search-and-rescue, relief, rehabilitation, reconstruction. Recovery may exceed (more resilient), match, or fall below pre-disaster level depending on aid and management.', 2),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Sketch the three plate boundary types.', 'Constructive (divergent): plates move apart, magma rises, mid-ocean ridges/rifts. Destructive (convergent): denser oceanic subducts beneath continental, trench/volcanic arc. Conservative (transform): plates slide past, earthquakes only. <svg viewBox="0 0 280 150" width="280" height="150" style="display:block;margin:6px auto"><g><rect x="10" y="40" width="40" height="40" fill="#A0A0A0"/><rect x="60" y="40" width="40" height="40" fill="#A0A0A0"/><polygon points="50,40 60,40 55,20" fill="#B00020"/><line x1="20" y1="60" x2="0" y2="60" stroke="#0B1E3F" marker-end="url(#a8)"/><line x1="90" y1="60" x2="110" y2="60" stroke="#0B1E3F" marker-end="url(#a8)"/><text x="55" y="100" font-size="8" fill="#0B1E3F" text-anchor="middle">Constructive</text></g><g><rect x="120" y="40" width="50" height="40" fill="#A0A0A0"/><polygon points="170,40 215,80 215,40" fill="#A0A0A0"/><polygon points="195,40 175,40 175,55" fill="#9CC3E5"/><polygon points="180,40 200,40 190,25" fill="#B00020"/><line x1="155" y1="60" x2="180" y2="60" stroke="#0B1E3F" marker-end="url(#a8)"/><line x1="200" y1="60" x2="180" y2="60" stroke="#0B1E3F" marker-end="url(#a8)"/><text x="170" y="100" font-size="8" fill="#0B1E3F" text-anchor="middle">Destructive</text></g><g><rect x="225" y="40" width="50" height="40" fill="#A0A0A0"/><line x1="250" y1="40" x2="250" y2="80" stroke="white" stroke-width="2"/><line x1="240" y1="50" x2="260" y2="50" stroke="#0B1E3F" stroke-dasharray="2 2"/><line x1="230" y1="35" x2="245" y2="35" stroke="#0B1E3F" marker-end="url(#a8)"/><line x1="270" y1="85" x2="255" y2="85" stroke="#0B1E3F" marker-end="url(#a8)"/><text x="250" y="100" font-size="8" fill="#0B1E3F" text-anchor="middle">Conservative</text></g><defs><marker id="a8" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#0B1E3F"/></marker></defs></svg>', 3),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'What drives plate movement? Explain mantle convection and ridge push/slab pull.', 'Heat from radioactive decay drives mantle convection cells. Hot rock rises at ridges (ridge push), cools and sinks; old, cold, dense oceanic lithosphere subducts and pulls the rest of the plate (slab pull). Slab pull dominates.', 4),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Distinguish primary and secondary effects of a volcanic eruption.', 'Primary: lava, pyroclastic flows, ashfall, gases. Secondary: lahars (mud flows), tsunamis, climate impact (Pinatubo 1991 cooled global T by 0.5°C), economic disruption, displacement.', 5),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Compare a shield with a composite (stratovolcano).', 'Shield: low-viscosity basaltic lava, gentle slopes, frequent effusive eruptions (Mauna Loa). Composite: high-viscosity andesitic lava, steep alternating ash/lava layers, infrequent explosive eruptions (Mt. St. Helens, Vesuvius).', 6),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'How are earthquakes measured?', 'Magnitude (energy): Richter scale (logarithmic, replaced by Moment Magnitude Mw above ~M5). Intensity (effects): Modified Mercalli (I-XII). Depth: shallow (<70 km) most damaging.', 7),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Distinguish primary and secondary effects of an earthquake.', 'Primary: ground shaking, surface rupture, building collapse. Secondary: tsunami, liquefaction, landslides, fires (gas mains), disease, economic loss. Secondary often kill more people than primary.', 8),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Explain how a tsunami forms.', 'Sudden vertical displacement of seabed (megathrust earthquake at subduction zone) lifts the entire water column. Long-wavelength waves travel at jet speed in deep ocean (~700 km/h), slow and steepen on the shelf, surge inland.', 9),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline a tropical storm and its formation conditions.', 'A rotating low-pressure system with sustained winds >119 km/h. Forms over oceans >26.5°C, depth >50 m, between 5° and 30° latitude (Coriolis effect needed), in low wind shear. Warm core driven by latent heat release.', 10),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'List the main hazards of a tropical storm.', 'High winds, torrential rain, storm surge, flooding, landslides. Storm surge typically causes most deaths in low-lying areas (Bangladesh 1970 cyclone — 300,000+ deaths).', 11),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline a wildfire as a hazard, including conditions favouring ignition.', 'Uncontrolled vegetation fire. Conditions: dry fuel (drought), high temperature, low humidity, strong wind, ignition source (lightning, human). Climate change is lengthening fire seasons (Australia 2019-20, California, Mediterranean).', 12),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline a contrasting case study of two earthquakes (HIC vs LIC).', 'Tohoku, Japan 2011 (Mw9.1): ~20,000 deaths mostly from tsunami, $235bn damage; advanced warning, building codes, swift recovery. Haiti 2010 (Mw7.0): ~230,000 deaths, weak buildings, slow recovery, lasting cholera outbreak.', 13),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Describe modification of vulnerability strategies.', 'Education, hazard mapping, prediction (seismic monitoring, weather forecasting), warning systems (Japan''s 1-min earthquake alert), insurance, building codes (base isolation, cross-bracing), drills, evacuation routes.', 14),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Explain why hazard impact varies between countries (development, governance).', 'Wealth funds prevention/response. Strong governance enforces codes, manages aid. Cultural factors influence perception. LICs lack early warning, hospitals, and reconstruction finance — so similar magnitudes cause higher death tolls.', 15),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Define hazard adjustment and provide three examples.', 'Adjustments are deliberate actions to reduce loss. Examples: zoning (no building on floodplains), retrofitting buildings, planting mangroves to absorb surges, community drills, micro-insurance for farmers.', 16),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Define VEI (Volcanic Explosivity Index).', 'A logarithmic 0-8 scale based on volume of ejecta and column height. VEI 0-2: effusive, frequent. VEI 5+: highly explosive, regional impact (Mt St Helens 1980 = 5; Pinatubo 1991 = 6; Tambora 1815 = 7).', 17),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline a multi-hazard zone.', 'Region exposed to several hazards (e.g. Philippines: typhoons, earthquakes, volcanism, tsunamis, landslides). Compound risk: one event can trigger another (typhoon -> landslide on volcanic slope). Increases vulnerability and complicates planning.', 18),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'Outline factors that affect hazard perception (experience, wealth, fatalism).', 'Wealth, education, religion, past experience, media coverage, role of government. Higher education and recent experience -> active mitigation. Fatalistic ''Acts of God'' acceptance -> passive response. Influences vulnerability.', 19),
  ('Geography', 'AQA', 'alevel', '1.3', 'Hazards', 'What is a supervolcano and where are they?', 'A volcano with VEI 8 — over 1000 km3 of ejecta, capable of triggering global cooling (volcanic winter). Yellowstone (USA), Toba (Indonesia, last erupted 74,000 yrs ago, ''Toba bottleneck''), Taupo (NZ). Dormant but monitored.', 20),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Distinguish space, place and locale.', 'Space: an area defined by coordinates. Place: space invested with meaning by people (Tuan). Locale: setting in which everyday life happens (Agnew). Place is therefore relational and dynamic.', 1),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Distinguish near and far places.', 'Near: places experienced directly through everyday life. Far: places known only through media, education or imagination. Globalisation blurs the distinction (instant communications can make distant events feel proximate).', 2),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Distinguish experienced and media places.', 'Experienced: known first-hand through visits and routines. Media: known via film, news, social media, books. Media representations may distort reality (e.g. ''sink-estate'' stereotypes).', 3),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define endogenous and exogenous factors that shape place.', 'Endogenous (internal): physical geography, demography, land use, economy, built environment, history. Exogenous (external): connections to other places, migration, capital flows, government policy, globalisation.', 4),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define topophilia and topophobia.', 'Topophilia (Tuan, 1974): the affective bond between people and place — love of place. Topophobia: fear or dislike of place — common in places associated with crime, decay, traumatic memory.', 5),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Distinguish insider and outsider perspectives.', 'Insider: born or long-resident, share traditions, language, networks; place-attached. Outsider: temporary or unfamiliar; may romanticise or stereotype. Status fluid — gentrifiers can shift between.', 6),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'How does globalisation affect place identity?', 'Increases similarity (clone towns, McDonaldisation), but also enables cultural hybridity (London curry, Liverpool Chinatown). Some places resist (CittaSlow, fair-trade towns); others rebrand to compete.', 7),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define place-meaning and place-identity.', 'Place-meaning: subjective values and emotions attached to place by individuals/groups. Place-identity: sense of self constructed through belonging to place (national, regional, neighbourhood).', 8),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Outline gentrification with one named example.', 'In-migration of higher-income residents into a previously low-income area, refurbishing housing and changing local amenities. Displaces original residents through rising rents. Examples: Notting Hill, Brixton, Hackney, Brooklyn.', 9),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Outline a rural rebranding strategy with an example.', 'Rebranding aims to attract visitors/investors. Cornwall: Eden Project (£2bn local economic impact since 2001), Hall for Cornwall, food/drink tourism, surf tourism, films like Doc Martin. Trade-offs: housing affordability for locals.', 10),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Outline an urban rebranding strategy with an example.', 'Liverpool One (2008) — £1bn shopping district. Capital of Culture 2008 boosted tourism. Albert Dock heritage waterfront. Tate Liverpool. But persistent inequality in Anfield/Everton wards.', 11),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'List four ways place is represented.', 'Statistics (census, IMD), films, novels, paintings, photographs, music, postcards, tourist boards, news media, social media (#hashtags create new place identities).', 12),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'How does the IMD measure deprivation?', 'UK Index of Multiple Deprivation combines seven domains: income, employment, education, health, crime, housing, living environment. Areas ranked into deciles. Allows place-by-place comparison of need.', 13),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define lived experience and how a researcher accesses it.', 'The everyday meanings of a place to its residents. Accessed through ethnography, interviews, oral histories, participant observation, mental maps, photo elicitation — qualitative methods that surface what statistics cannot.', 14),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Explain the role of TNCs in changing places.', 'TNCs alter place economies by opening/closing branches, sourcing globally, and homogenising the high street (clone towns). Detroit''s decline tracked GM/Ford restructuring; Bangalore''s rise tracked IT outsourcing.', 15),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Compare a contrasting place study (your own + a contrasting one).', 'Choose two places (e.g. local urban + rural Cornwall), compare endogenous and exogenous factors, demographic and economic profiles, representations, lived experiences and management strategies — the ''Changing Places'' core skill.', 16),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Outline how power shapes place (gentrification politics).', 'Local authorities, developers and capital decide which places get investment. Power asymmetries displace less powerful (low-income, ethnic minorities). Resistance: campaigns (Save Latin Village, Tottenham), community land trusts, rent controls.', 17),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define resilience of place.', 'A place''s ability to absorb shocks (flooding, deindustrialisation, pandemics) and adapt. Drivers: economic diversity, social capital, governance, infrastructure. Detroit struggled; Pittsburgh transitioned to medicine/education ''eds and meds''.', 18),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'How does diaspora shape place identity?', 'Migrants reshape places of origin (remittances, return migration) and destination (cultural quarters, transnational networks). London Bangladeshi diaspora invests in Sylhet; Brick Lane''s curry mile reflects east London Bangladeshi identity.', 19),
  ('Geography', 'AQA', 'alevel', '2.1', 'Changing Places', 'Define ''place is socially constructed''.', 'Place meaning is created through human practice, language and representation rather than fixed by physical geography. The same physical site can be ''heritage,'' ''slum,'' ''opportunity'' or ''problem'' depending on who narrates it.', 20),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define urbanisation, suburbanisation, counter-urbanisation, re-urbanisation.', 'Urbanisation: rising % living in cities. Suburbanisation: outward growth from city centres. Counter-urbanisation: net movement to rural areas (1970s UK, accelerated by Covid). Re-urbanisation: return to inner cities (e.g. Docklands).', 1),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Sketch the Burgess concentric model.', 'CBD core, then transition zone, working-class housing, middle-class housing, commuter zone — based on 1920s Chicago. Assumes uniform land surface and a single centre. <svg viewBox="0 0 200 160" width="200" height="160" style="display:block;margin:6px auto"><circle cx="100" cy="80" r="70" fill="#9CC3E5" fill-opacity="0.3" stroke="#0B1E3F"/><circle cx="100" cy="80" r="55" fill="#9CC3E5" fill-opacity="0.4" stroke="#0B1E3F"/><circle cx="100" cy="80" r="40" fill="#9CC3E5" fill-opacity="0.5" stroke="#0B1E3F"/><circle cx="100" cy="80" r="25" fill="#9CC3E5" fill-opacity="0.6" stroke="#0B1E3F"/><circle cx="100" cy="80" r="12" fill="#0B1E3F"/><text x="100" y="84" font-size="9" fill="white" text-anchor="middle">CBD</text><text x="100" y="65" font-size="7" fill="#0B1E3F" text-anchor="middle">transition</text><text x="100" y="48" font-size="7" fill="#0B1E3F" text-anchor="middle">working-class</text><text x="100" y="32" font-size="7" fill="#0B1E3F" text-anchor="middle">middle-class</text><text x="100" y="18" font-size="7" fill="#0B1E3F" text-anchor="middle">commuter</text></svg>', 2),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'How does Hoyt''s sector model differ from Burgess?', 'Hoyt (1939): sectors radiate from CBD along transport routes. Higher-income corridors keep their character outwards; industry follows transport. Better fits cities shaped by railways/roads.', 3),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Outline the multiple nuclei (Harris-Ullman) model.', 'Cities grow around several nodes (CBD, ports, universities, airports), not just one centre. Better captures large modern cities (Los Angeles, Greater London) than Burgess or Hoyt.', 4),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define megacity, world city and global city.', 'Megacity: >10 million inhabitants (Tokyo, Delhi, Shanghai). World city: significant global political/economic influence (Friedmann). Global city: command-and-control nodes for finance and producer services (Sassen — NYC, London, Tokyo).', 5),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'List the main causes of the urban heat island effect.', 'Albedo of dark surfaces, anthropogenic heat (cars, AC, industry), reduced evapotranspiration, urban canyon multiple reflections, less wind, air pollution that traps long-wave radiation.', 6),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Explain photochemical smog formation.', 'Vehicle NOx and VOCs react in sunlight to form ground-level ozone and PAN. Worst in still, hot, sunny weather over cities (Los Angeles, Beijing, Mexico City). Damages respiratory health and crops.', 7),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'How does urbanisation alter the water cycle?', 'Impermeable surfaces increase runoff; storm drains concentrate it. Result: faster lag times, higher peak discharge — flashier hydrographs and flash flooding. SUDS (rain gardens, swales, permeable paving) try to mitigate.', 8),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define the multiplier effect in an urban economy.', 'Initial investment (TNC HQ, university, regeneration) creates direct jobs and demand for local services, generating further indirect/induced jobs. The reverse — the negative multiplier — drives spirals of decline.', 9),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Outline causes and consequences of urban deprivation.', 'Deindustrialisation, structural unemployment, poor housing, low investment, weak schools. Consequences: cycles of poverty, spatial inequality, mental and physical ill-health, social unrest. Measured by IMD.', 10),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Outline an urban regeneration scheme (London Docklands).', '1981 LDDC established. £8.7bn investment by 1998. Canary Wharf, DLR, City Airport. Jobs in the area rose from ~27,000 (1981) to ~85,000 (1998). Critique: original communities largely excluded; gentrification displaced low-income residents.', 11),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'List four sustainable urban strategies.', 'Compact city design, public transport (BRT, metro, cycle networks), renewable energy, green roofs and parks, mixed-use development, district heating, water recycling, community engagement (Curitiba, Freiburg, Copenhagen).', 12),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'How does Curitiba (Brazil) illustrate sustainable transport?', 'Bus Rapid Transit launched 1974; >2 million daily passengers; tube-stations speed boarding; integrated land-use planning along five axes; 70% commuters use BRT. Replicated in Bogota (TransMilenio).', 13),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define ecological footprint and how cities increase it.', 'Land/water area needed to provide resources and absorb waste. Cities concentrate consumption — London''s footprint is ~125x its area; rich cities outsource emissions to producing regions.', 14),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define ethnic enclave and outline reasons for clustering.', 'A neighbourhood with high concentration of one ethnic group. Reasons: chain migration, mutual support, language/cultural amenities, discrimination in housing markets. Examples: Tower Hamlets (Bangladeshi), Brixton (Caribbean).', 15),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Compare a UK city with a megacity in the developing world.', 'London (~9 million, planned, formal housing, declining inner-city deprivation) vs Mumbai (~22 million, Dharavi slum hosts ~1 million, informal economy >50%, intense pollution, coastal flood risk).', 16),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'List four challenges of urban waste management.', 'Volume (UK ~26 Mt municipal/yr), composition (plastics, e-waste, food), illegal dumping, landfill capacity, methane emissions. Strategies: reduce/reuse/recycle, anaerobic digestion, energy-from-waste, EPR schemes, deposit return.', 17),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'Define a smart city.', 'A city that uses ICT, sensors and big data to manage assets, energy, traffic and services efficiently. Examples: Singapore, Songdo (Korea), Barcelona''s sensors for parking, lighting, waste. Critics: privacy, equity gap.', 18),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'List three drivers of counter-urbanisation.', 'Improved transport/IT (commute, remote work), perception of better quality of life (lower crime, cleaner air, schools), housing affordability, retirement. Covid-19 accelerated UK ''race for space'' (London out-migration ~80,000 in 2020-21).', 19),
  ('Geography', 'AQA', 'alevel', '2.2', 'Contemporary Urban Environments', 'How does urban form influence energy use?', 'Compact, mixed-use cities (Barcelona, Hong Kong) have lower per-capita transport energy than sprawled, car-dependent ones (Atlanta, Houston). Density permits mass transit, district heating, shorter trips.', 20),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Explain the Demographic Transition Model (DTM) stages.', 'Stage 1 high BR/DR, low NIR (pre-industrial). Stage 2 DR falls, BR high, rapid growth. Stage 3 BR falls. Stage 4 low BR/DR. Stage 5 (added) DR>BR, decline (Japan, Italy). <svg viewBox="0 0 280 160" width="280" height="160" style="display:block;margin:6px auto"><line x1="30" y1="135" x2="270" y2="135" stroke="#0B1E3F"/><line x1="30" y1="135" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 35 Q60 35 90 70 Q130 110 180 120 Q220 120 270 125" stroke="#B00020" stroke-width="1.5" fill="none"/><path d="M30 35 Q60 35 100 50 Q140 80 200 110 Q235 115 270 115" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="80" y1="20" x2="80" y2="140" stroke="#0B1E3F" stroke-dasharray="2 2" stroke-width="0.5"/><line x1="130" y1="20" x2="130" y2="140" stroke="#0B1E3F" stroke-dasharray="2 2" stroke-width="0.5"/><line x1="190" y1="20" x2="190" y2="140" stroke="#0B1E3F" stroke-dasharray="2 2" stroke-width="0.5"/><line x1="230" y1="20" x2="230" y2="140" stroke="#0B1E3F" stroke-dasharray="2 2" stroke-width="0.5"/><text x="55" y="150" font-size="8" fill="#0B1E3F" text-anchor="middle">1</text><text x="105" y="150" font-size="8" fill="#0B1E3F" text-anchor="middle">2</text><text x="160" y="150" font-size="8" fill="#0B1E3F" text-anchor="middle">3</text><text x="210" y="150" font-size="8" fill="#0B1E3F" text-anchor="middle">4</text><text x="250" y="150" font-size="8" fill="#0B1E3F" text-anchor="middle">5</text><text x="265" y="32" font-size="8" fill="#B00020" text-anchor="end">BR</text><text x="265" y="112" font-size="8" fill="#0B1E3F" text-anchor="end">DR</text></svg>', 1),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Read a population pyramid: youthful vs ageing.', 'Youthful pyramid (LIC): wide base, narrow top — high BR, short life expectancy (Niger). Ageing pyramid (HIC): narrow base, wide top — low BR, long life expectancy (Japan, Germany). Indicates dependency ratio.', 2),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define dependency ratio and give the formula.', 'DR = (under 15 + over 64) / (15-64) × 100. Higher DR means working population supports more dependants — strain on welfare and pensions in HICs, on schools and food in LICs.', 3),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Compare neo-Malthusian and Boserupian views.', 'Malthus/neo-Malthus: population grows geometrically while food grows arithmetically -> famine. Boserup: population pressure drives agricultural innovation. Real history fits both (Green Revolution, but soil exhaustion).', 4),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'List four physical influences on population distribution.', 'Climate (temperature, rainfall), relief, soil fertility, water availability, vegetation, drainage, latitude/altitude. People cluster in fertile lowlands, river valleys and coasts.', 5),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define carrying capacity and overpopulation.', 'Carrying capacity (K): the maximum population a region can support sustainably. Overpopulation: population exceeds K, causing resource depletion and environmental degradation.', 6),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'List four push and pull factors of migration.', 'Push: war, poverty, drought, persecution, lack of jobs/education. Pull: jobs, family reunification, peace, education, healthcare, freedom. Lee''s model adds intervening obstacles (cost, border controls).', 7),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Outline the demographic dividend.', 'When the working-age population is much larger than dependants, savings and investment can rise — boosting growth (East Asia 1960-90). Requires education, jobs and gender equality to be realised.', 8),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define epidemiological transition (Omran).', 'Disease patterns shift as a society develops: from infectious diseases (TB, cholera) and famine, to chronic diseases (heart disease, cancer), to ''emerging'' diseases (Covid-19, antibiotic-resistant infections).', 9),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Outline a contrasting health case study.', 'UK NHS: universal healthcare, ageing population, NCDs dominate, life expectancy ~81. Sub-Saharan Africa: HIV/AIDS, malaria, malnutrition; life expectancy 60-65 but rising as ART scaled up.', 10),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Outline anti- and pro-natalist policies with examples.', 'Anti-natalist: China''s One-Child Policy (1979-2015) — enforced quotas, social pressures; created sex imbalance, ageing. Pro-natalist: France''s family allowance, Singapore''s ''Have Three or More'' (1987), Hungary tax breaks.', 11),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'How does climate influence agriculture?', 'Temperature determines growing season; rainfall controls choice of crops (irrigation in arid zones); extreme events (drought, frost, hail, floods) reduce yields; climate change shifts viable areas (vine UK, decline in Iberia).', 12),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'List four agricultural strategies to feed a growing population.', 'Green Revolution (HYV crops, irrigation, fertiliser), GM crops, vertical farming, precision agriculture, irrigation, soil conservation, fair-trade, dietary shift to less meat.', 13),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Compare population dynamics of two contrasting countries.', 'Niger: TFR ~6.7, median age 15, rapidly growing youthful population, food security under pressure. Japan: TFR ~1.15 (2025, a record low), median age ~50, shrinking labour force, rising old-age dependency.', 14),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Outline forecast effects of climate change on global population.', 'Disruption to food/water in vulnerable regions (Sahel, South Asia), migration pressures (climate refugees), heat-related mortality, expanded vector-borne disease. IPCC: hundreds of millions at risk by 2050.', 15),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define resource pressure and one strategy to relieve it.', 'Demand for water, food, energy and land beyond what local environments can supply sustainably. Strategies: efficiency, recycling, demand management, shifting consumption patterns, technological innovation, international trade.', 16),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Outline how vector-borne disease distribution is influenced by climate.', 'Mosquitoes (malaria, dengue) require warmth and standing water. Climate change is shifting ranges polewards and to higher altitudes (highland malaria in Kenya). Tsetse fly limits African livestock to certain zones.', 17),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Why is globalisation linked to pandemics?', 'Air travel moves pathogens across continents in hours (SARS 2003, H1N1 2009, Covid-19 2020). Urbanisation concentrates susceptible populations. Habitat encroachment increases zoonotic spillover (Ebola, Nipah, Covid-19).', 18),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define soil degradation and its impact on food security.', 'Decline in soil fertility through erosion, salinisation, compaction or contamination. Affects ~33% of global land. Reduces yields, increases fertiliser dependence, releases stored carbon. Worst in semi-arid Africa, South Asia.', 19),
  ('Geography', 'AQA', 'alevel', '2.3', 'Population & the Environment', 'Define a food desert.', 'An urban area with poor access to affordable, nutritious food (low income, no supermarkets within walking distance, reliance on convenience stores). Linked to obesity and diet-related diseases. Common in deprived inner-city UK and US neighbourhoods.', 20),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Define resource and resource security.', 'Resource: anything natural that humans use to sustain life or generate wealth. Resource security: assured access to a resource (water, food, energy) at affordable cost, in adequate amount, reliably.', 1),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Distinguish stock, flow and renewable resources.', 'Stock (non-renewable): fixed amount, depleted by use (fossil fuels, minerals). Flow (renewable): continuously replenished (solar, wind, water). Critical: renewable in principle but fragile under stress (forests, fisheries).', 2),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'List the components of the energy mix.', 'Coal, oil, natural gas (fossil), nuclear, hydro, wind, solar, biomass/biofuel, geothermal, tidal/wave. Mix varies by country: France ~65-70% nuclear, Norway ~88-90% hydro, Saudi Arabia oil- and gas-dominant.', 3),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Describe the global pattern of energy supply and demand.', 'Supply concentrated in oil/gas-rich states (Middle East, Russia, USA). Demand greatest in HICs and rapidly industrialising NEEs (China, India). Transit chokepoints (Strait of Hormuz, Malacca, Bab el-Mandeb) create geopolitical risk.', 4),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Define peak oil and Hubbert''s curve.', 'Peak oil: the point of maximum extraction, after which production declines. Hubbert''s 1956 prediction of US peak in ~1970 was broadly correct (until shale revolution from 2008 reopened US production).', 5),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Distinguish unconventional and conventional fossil fuel sources.', 'Conventional: vertically drilled, naturally pooled, easily extracted. Unconventional: shale gas/oil (fracking), tar sands, deep-water, Arctic — higher cost, more environmental impact (water use, emissions, induced seismicity).', 6),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline two sources of mineral resource demand growth.', 'Renewables: lithium for batteries, rare earths for wind turbines and EVs, copper for grids. Urbanisation: steel, cement, aluminium for construction. Both increasing pressure on reserves and fuelling new geopolitics.', 7),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Distinguish blue, green and grey water.', 'Blue: liquid surface and groundwater. Green: rainwater stored in soil and used by plants. Grey: wastewater volume needed to dilute pollution to safe levels. Useful for agricultural water footprint analysis.', 8),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Define water scarcity and water stress.', 'Water stress: <1700 m3 per person per year. Water scarcity: <1000 m3. Absolute scarcity: <500 m3. Causes: physical (low rainfall) or economic (lack of infrastructure). Affects ~2 billion people.', 9),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline causes and consequences of water scarcity (Aral Sea).', 'Soviet 1960s diversion of Amu/Syr Darya for cotton irrigation; Aral lost ~90% volume by 2010. Consequences: collapse of fisheries, salinised soils, dust storms, public health crisis, climate change (loss of moderating effect).', 10),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'List four food security threats.', 'Climate change/extreme weather, soil degradation, water scarcity, pests/disease, conflict, market shocks, supply chain breakdowns (Covid), trade restrictions, wastage (~30% globally).', 11),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline strategies to improve food security.', 'Boost productivity (HYV, irrigation, mechanisation, GM), reduce waste, diversify diets, store buffer stocks, improve roads/infrastructure, fair-trade, subsidies, climate-smart agriculture, land reform.', 12),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Define a transboundary resource and give an example.', 'A resource (river, aquifer, fishery) that crosses political borders, requiring cooperation. Examples: Nile (Egypt-Sudan-Ethiopia GERD dispute), Mekong, Indus Waters Treaty (India-Pakistan, 1960; held in abeyance by India since 2025).', 13),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline the geopolitics of energy in Russia/Ukraine.', 'Russia supplied ~40% of EU gas pre-2022. Invasion of Ukraine triggered EU diversification (Norwegian gas, US LNG, accelerated renewables, restart of coal). Energy weaponised; Nord Stream sabotaged.', 14),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline a sustainable resource management approach.', 'Reduce, reuse, recycle. Circular economy. Resource efficiency (water-saving, energy-efficient buildings). Local sourcing. Restoration (rewetting peatlands). Consumer education. Carbon pricing. Polluter-pays principle.', 15),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Why is the energy transition geographically uneven?', 'Wealth funds capital-heavy technologies (LICs lag); natural endowment (sun, wind) varies; fossil fuel rents resist change; politics influences ambition (China''s solar dominance vs Saudi Arabia''s oil dependency).', 16),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Why are rare earth elements geopolitically significant?', '17 metals essential for magnets, EVs, wind turbines, smartphones, defence. China mines ~70% of global output and controls ~90% of refining and separation (USGS, 2025). Concentrated supply -> strategic vulnerability. EU and US developing domestic mines and recycling.', 17),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline the renewable energy transition.', 'Global renewable share rose from ~20% (2010) to ~30% (2024) of electricity. Cost falls — solar PV ~90% cheaper since 2010. Wind, solar dominate new capacity. Challenges: intermittency, storage, grid upgrades, land use, mineral demand.', 18),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Outline conflict over a transboundary water resource.', 'Nile: Ethiopia''s Grand Ethiopian Renaissance Dam (reservoir filled 2020-24, dam inaugurated September 2025) can cut flow to Egypt and Sudan. Egypt, dependent on the Nile for ~95% of its water, calls it an existential threat. No binding filling/operating agreement has been reached.', 19),
  ('Geography', 'AQA', 'alevel', '2.4', 'Resource Security', 'Define the resource curse.', 'When countries rich in natural resources experience worse development outcomes than resource-poor peers. Causes: rent-seeking, corruption, currency overvaluation (''Dutch disease''), conflict (DRC, Nigeria''s Niger Delta), authoritarianism (Venezuela).', 20),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define globalisation and list its five dimensions.', 'The growing integration of economies, societies and cultures through cross-border flows. Dimensions: capital (FDI, portfolio investment, remittances), labour (migration), products (goods), services (finance, tourism, offshored work) and information (data, ideas, media).', 1),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'List six factors that drive globalisation.', 'Transport technology (containerisation from 1956, air freight); ICT and submarine fibre-optic cables; financial deregulation and 24-hour markets; management and information systems (just-in-time, global logistics); legal and security frameworks (contract law, IP protection); trade agreements (GATT 1947, WTO 1995).', 2),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define global marketing with an example.', 'Treating the world as a single market and selling a standardised product under a standardised brand, lightly adapted for local taste (glocalisation). McDonald''s sells a common core menu worldwide but adds region-specific items such as the McSpicy Paneer in India.', 3),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Give scale figures for the four main global flows.', 'FDI: $1.6 trillion in 2025, up 6%, with the top 20 host economies taking over 80% (UNCTAD 2026). Migrants: 304 million in 2024, 3.7% of world population (UN DESA). Remittances: about $685 billion to low- and middle-income countries in 2024 (World Bank) — more than FDI or aid. Merchandise trade value: up 6.5% year-on-year to a record over the first nine months of 2025 (WTO).', 4),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define interdependence and give its four dimensions.', 'Mutual dependence where events in one place have consequences for another. Economic (Taiwanese chip shortages halt German car plants), political (EU, NATO, ASEAN obligations), social (diaspora ties and remittances), environmental (emissions anywhere warm everywhere).', 5),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'How do unequal power relations let some states drive global systems?', 'Weighted voting at the IMF and World Bank gives the USA an effective veto over decisions needing an 85% majority. The five permanent Security Council members each hold a veto. The dollar''s role as reserve and settlement currency allows secondary sanctions with global reach. The World Bank presidency has by convention always gone to an American.', 6),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Explain comparative advantage and two of its weaknesses.', 'Ricardo: countries gain by specialising in what they produce at lowest opportunity cost and trading for the rest. Weaknesses: it assumes capital and labour are immobile (they are not) and that terms of trade are fair; it ignores the volatility of commodity prices and the power of TNCs to set prices within their own supply chains.', 7),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define tariff escalation and explain why it matters.', 'Import duties rise with the degree of processing — low or zero on raw cocoa beans, higher on cocoa butter, higher still on finished chocolate. It makes it cheaper to export raw material than to add value at source, so producer countries stay locked into primary exports and the processing profit stays in the importing region.', 8),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'List six barriers to market access for developing-country exporters.', 'Tariffs (with peaks on agriculture and textiles); tariff escalation; quotas and non-tariff barriers (standards, labelling, certification); subsidies to HIC producers; trade blocs with common external tariffs; weak infrastructure, poor ports and landlocked geography.', 9),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Distinguish the main types of trade bloc, with examples.', 'Free trade area — no internal tariffs (USMCA, AfCFTA). Customs union — plus a common external tariff. Common market — plus free movement of labour and capital. Economic union — plus shared policy and often currency (EU: 27 members, 20 in the eurozone). ASEAN admitted Timor-Leste as its 11th member on 26 October 2025; the UK joined the CPTPP in December 2024, showing blocs need not be regional.', 10),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Describe the spatial organisation of a TNC.', 'Headquarters and R&D in HICs for skills, finance and IP protection; manufacturing and assembly in lower-cost economies; regional sales and service divisions near markets. Backward linkages run to suppliers, forward linkages to distributors — a local multiplier develops only where those linkages are sourced locally.', 11),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Outline Apple as a specified TNC case study.', 'Design and marketing in Cupertino, California; advanced processors fabricated by TSMC in Taiwan; components from South Korea, Japan and China; assembly by Foxconn, Pegatron and Tata Electronics in China, India and Vietnam. Its supplier list covers around 200 firms and about 98% of direct spend. Foxconn Zhengzhou employs well over 100,000 at peak. Assembly is diversifying to India (roughly 15-20% of iPhones by end-2025). Criticisms: overtime and labour conditions, and tax — the EU Court of Justice upheld the Irish state aid ruling in September 2024, requiring about 13 billion euro in back tax.', 12),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define transfer pricing.', 'Setting the internal price at which a TNC''s subsidiaries trade components, services or intellectual property with each other, so that declared profit shifts into low-tax jurisdictions and away from where production and sales actually occur. It is the main mechanism behind corporate tax avoidance in global supply chains.', 13),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Summarise world trade in cocoa as a food commodity case study.', 'Côte d''Ivoire and Ghana grow roughly 60% of world cocoa on smallholdings; processing and manufacture happen mainly in Europe and North America, and tariff escalation keeps it there. Prices peaked near $12,500 a tonne in December 2024 then fell back below about $6,000 through 2025-26, so farmers absorb the volatility. Responses: the Ivorian-Ghanaian Living Income Differential (2019); the Fairtrade Minimum Price rising 45% to $3,500 a tonne from 1 October 2026; and the EU Deforestation Regulation, whose compliance costs fall hardest on smallholders.', 14),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define global governance and name the main post-1945 institutions.', 'The rules, norms, laws and institutions regulating international affairs in the absence of a world government; compliance rests on treaty obligation, reciprocity and reputation rather than coercion. UN (1945, 193 members), IMF and World Bank (Bretton Woods 1944), WTO (1995, from GATT 1947, 166 members covering about 98% of world trade).', 15),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Give three structural criticisms of global governance institutions.', 'UN Security Council: five permanent members each hold a veto, freezing the 1945 power balance. IMF and World Bank: voting weighted by quota, giving the USA an effective veto over 85% decisions, and structural adjustment in the 1980s-90s imposed severe social costs. WTO: consensus among 166 members stalled the Doha round, and the Appellate Body has been paralysed since December 2019 because the USA blocks appointments — 61 members now use the interim MPIA arrangement instead.', 16),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Define the global commons and name the four of them.', 'Resource domains beyond the political reach of any single state to which all nations have a legal right of access: the high seas, the atmosphere, Antarctica and outer space. Hardin (1968) argued unmanaged commons tend to ruin; Ostrom (Nobel Prize, 2009) showed they can be sustained where boundaries, monitoring and graduated sanctions exist. AQA''s tension: the right of all to the benefits must be reconciled with the need to protect them.', 17),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Outline UNCLOS and its maritime zones.', 'Adopted 1982, in force 1994, 172 States Parties by 2026 (the USA has still not ratified). Territorial sea 12 nautical miles (full sovereignty); contiguous zone 24 nm (customs and immigration enforcement); EEZ 200 nm (rights over resources); continental shelf to 350 nm on geological evidence; high seas beyond, with freedom of navigation and fishing for all; and the deep seabed "Area", declared the common heritage of mankind and administered by the International Seabed Authority.', 18),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'What is the High Seas (BBNJ) Treaty and why does it matter?', 'Adopted June 2023, it reached 60 ratifications on 19 September 2025 and entered into force on 17 January 2026 (around 94 parties and 145 signatories by September 2026). It creates the first route to marine protected areas on the high seas, requires environmental impact assessment there, and shares the benefits of marine genetic resources. It closes the gap UNCLOS left and makes the 30% ocean protection target for 2030 reachable — but binds only its parties and is enforcement-untested.', 19),
  ('Geography', 'AQA', 'alevel', '2.5', 'Global Systems & Global Governance', 'Summarise the Antarctic Treaty System and assess its effectiveness.', 'Antarctic Treaty 1959 (in force 1961): 58 parties, 29 Consultative Parties deciding by consensus; peaceful use only, freedom of science, no nuclear activity, claims frozen (Article IV), open inspection at any time (Article VII). CCAMLR 1980 manages Southern Ocean fishing by an ecosystem approach and agreed the 1.55 million km² Ross Sea MPA in 2016. Madrid Protocol 1991 (in force 1998) bans mineral activity; from 2048 a review may be requested, but change still needs unanimity. Strengths: demilitarisation, no mining, frozen claims, real inspection. Weaknesses: consensus lets Russia and China block the Weddell Sea, East Antarctic and Peninsula MPAs (again in October 2025); the Area 48 krill trigger of 620,000 tonnes was hit for the first time in 2025; tourism (118,491 visitors in 2024-25) is self-regulated by IAATO; and no Antarctic instrument can slow warming caused from outside.', 20),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Define the geography NEA (Non-Examined Assessment).', 'A 3,000-4,000 word independent investigation worth 20% of A-Level. Student-chosen geographical question/hypothesis, four days minimum fieldwork (one outside class), uses primary and secondary data.', 1),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'List the six stages of an NEA investigation.', '1) Question/hypothesis. 2) Plan and methodology. 3) Data collection. 4) Data presentation. 5) Analysis and interpretation. 6) Conclusion and evaluation. All must show geographical reasoning.', 2),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Distinguish primary and secondary data.', 'Primary: collected by you in the field (questionnaires, measurements, photographs). Secondary: from existing sources (census, ONS, IMD, Met Office). Mix of both gives validity and triangulation.', 3),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Distinguish quantitative and qualitative data.', 'Quantitative: numerical and measurable (footfall, beach gradient, pH). Qualitative: descriptive and contextual (interviews, photographs, mental maps, environmental impact assessments).', 4),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'List four sampling techniques.', 'Random (using random number tables), systematic (every nth), stratified (subgroups proportional to population), opportunistic/convenience (where access permits). Choice depends on question, time and access.', 5),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Define accuracy, reliability and validity.', 'Accuracy: closeness to true value. Reliability: same result if repeated. Validity: data measures what you intend. NEA evaluation must address all three with specific examples from your method.', 6),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'List four ways to mitigate fieldwork risk.', 'Risk assessment, group working, weather monitoring, mobile phones, first-aid kit, hi-viz clothing, supervisor contact, awareness of tides/cliffs/traffic. Required by examination board.', 7),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Name four data presentation techniques.', 'Choropleth maps, isoline maps, dot maps, proportional symbols, line graphs, bar charts, scatter graphs with line of best fit, pie charts, kite diagrams, radar charts, GIS overlays.', 8),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'When use Spearman''s rank correlation coefficient?', 'When you want to test whether two ranked variables (e.g. distance from CBD vs pedestrian count) correlate. Result lies between −1 and +1; strength compared against critical values for significance.', 9),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'When use a chi-squared test?', 'When you want to compare observed frequencies (e.g. land-use type counts) with expected frequencies. Tests whether differences are statistically significant against critical values for given degrees of freedom.', 10),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Define standard deviation and what it tells you.', 'A measure of spread around the mean. Small SD: data clustered (consistent). Large SD: data dispersed. Used to compare variability between two samples (e.g. sediment size at two beaches).', 11),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'List four ways to measure river velocity.', 'Float method (orange/cork over fixed distance), flowmeter, dye tracing, calculated from cross-section + discharge. Repeat at multiple cross-sections; average for accuracy.', 12),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Outline how to investigate a coastal hypothesis.', 'Hypothesis e.g. ''Beach gradient steepens away from the dominant wave direction''. Methods: profile every 50 m using clinometer, measure pebble size with calipers, photograph features, secondary wind-direction data.', 13),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Outline how to investigate an urban question.', 'Question e.g. ''How does environmental quality vary along a transect from CBD to suburb?''. Use environmental quality survey, pedestrian count, land-use mapping, IMD secondary data, photographs at evenly spaced sites.', 14),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'How should you reference and avoid plagiarism in NEA?', 'Cite all secondary sources with author, date and title; use Harvard or footnotes consistently; quote directly with quotation marks; sign the JCQ declaration of authenticity, countersigned by your teacher. Centres routinely use plagiarism-detection software.', 15),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Outline what an evaluation should cover.', 'Strengths and limitations of method; sample size and representativeness; equipment accuracy; alternative approaches; how findings link to wider geographical theory; suggestions for further research.', 16),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Why is a pilot study useful?', 'A small-scale trial run of your method that highlights problems before main data collection: ambiguous questions, equipment issues, time required, sampling site suitability. Saves time and improves reliability.', 17),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'How can GIS be used in fieldwork?', 'Pre-fieldwork: identify sample sites, layer secondary data (IMD, flood risk, OS maps). During: GPS tagging photographs and measurements. After: choropleth maps, hot-spot analysis, buffer zones, network analysis. Software: ArcGIS, QGIS (free).', 18),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'List four ethical considerations in fieldwork.', 'Informed consent for interviews; anonymising data (no real names without permission); respect for cultural sensitivities; avoid disturbing protected sites/wildlife; consider safeguarding when working with under-18s; honest reporting (no fabrication).', 19),
  ('Geography', 'AQA', 'alevel', '3.1', 'Fieldwork & Investigation', 'Define triangulation of methods.', 'Using multiple data sources or methods to investigate the same question and cross-check findings (e.g. environmental quality survey + photograph + interview + secondary IMD data). Increases validity and confidence in conclusions.', 20)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

